    print(f"GC thresholds: {gc.get_threshold()}")
    print(f"GC counts: {gc.get_count()}")

    # 순환 참조 생성
    class Node:
        def __init__(self):
            self.ref = None

    a = Node()
    b = Node()
    a.ref = b
    b.ref = a  # 순환 참조

    del a, b  # 레퍼런스 카운팅으로 해제 불가

    # 강제 GC 실행
    collected = gc.collect()
    print(f"Objects collected: {collected}")

if __name__ == "__main__":
    memory_management_demo()
```

