## 2. Pipe와 Named Pipe

### 2.1 익명 파이프 (Anonymous Pipe)

부모-자식 프로세스 간의 단방향 통신 채널입니다.

```
                    Kernel Buffer
Parent              ┌──────────────┐              Child
┌───────┐  write()  │              │  read()   ┌───────┐
│ fd[1] │ ────────► │  ░░░░░░░░░░  │ ────────► │ fd[0] │
└───────┘           │  Pipe Buffer │           └───────┘
                    └──────────────┘
                    (기본 65536 bytes)
```

#### C 구현

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>

#define BUFFER_SIZE 256

int main() {
    int pipefd[2];  // pipefd[0]: 읽기, pipefd[1]: 쓰기
    pid_t pid;
    char buffer[BUFFER_SIZE];

    // 파이프 생성
    if (pipe(pipefd) == -1) {
        perror("pipe");
        exit(EXIT_FAILURE);
    }

    pid = fork();

    if (pid == -1) {
        perror("fork");
        exit(EXIT_FAILURE);
    }

    if (pid == 0) {
        // 자식 프로세스: 읽기만 수행
        close(pipefd[1]);  // 쓰기 끝 닫기

        ssize_t bytes_read;
        while ((bytes_read = read(pipefd[0], buffer, BUFFER_SIZE)) > 0) {
            printf("Child received: %.*s", (int)bytes_read, buffer);
        }

        close(pipefd[0]);
        exit(EXIT_SUCCESS);

    } else {
        // 부모 프로세스: 쓰기만 수행
        close(pipefd[0]);  // 읽기 끝 닫기

        const char *messages[] = {
            "Hello from parent!\n",
            "This is IPC via pipe.\n",
            "Goodbye!\n"
        };

        for (int i = 0; i < 3; i++) {
            write(pipefd[1], messages[i], strlen(messages[i]));
            usleep(100000);  // 100ms 대기
        }

        close(pipefd[1]);  // EOF 전송
        wait(NULL);
    }

    return 0;
}
```

#### 양방향 파이프 통신

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>

int main() {
    int parent_to_child[2];
    int child_to_parent[2];
    pid_t pid;

    // 두 개의 파이프 생성
    pipe(parent_to_child);
    pipe(child_to_parent);

    pid = fork();

    if (pid == 0) {
        // 자식 프로세스
        close(parent_to_child[1]);  // P→C 쓰기 닫기
        close(child_to_parent[0]);  // C→P 읽기 닫기

        char buffer[256];
        int num;

        // 부모로부터 숫자 받기
        read(parent_to_child[0], buffer, sizeof(buffer));
        num = atoi(buffer);
        printf("Child: Received %d, sending back %d\n", num, num * 2);

        // 결과 전송
        sprintf(buffer, "%d", num * 2);
        write(child_to_parent[1], buffer, strlen(buffer) + 1);

        close(parent_to_child[0]);
        close(child_to_parent[1]);
        exit(0);

    } else {
        // 부모 프로세스
        close(parent_to_child[0]);  // P→C 읽기 닫기
        close(child_to_parent[1]);  // C→P 쓰기 닫기

        char buffer[256];

        // 자식에게 숫자 전송
        sprintf(buffer, "%d", 42);
        write(parent_to_child[1], buffer, strlen(buffer) + 1);

        // 결과 받기
        read(child_to_parent[0], buffer, sizeof(buffer));
        printf("Parent: Received result: %s\n", buffer);

        close(parent_to_child[1]);
        close(child_to_parent[0]);
        wait(NULL);
    }

    return 0;
}
```

#### Python 구현

```python
import os
import sys

def pipe_example():
    """Python에서의 파이프 사용 예제"""

    # 파이프 생성
    read_fd, write_fd = os.pipe()

    pid = os.fork()

    if pid == 0:
        # 자식 프로세스
        os.close(write_fd)  # 쓰기 끝 닫기

        # 파일 객체로 변환
        with os.fdopen(read_fd, 'r') as reader:
            for line in reader:
                print(f"Child received: {line.strip()}")

        sys.exit(0)

    else:
        # 부모 프로세스
        os.close(read_fd)  # 읽기 끝 닫기

        with os.fdopen(write_fd, 'w') as writer:
            messages = ["Hello", "World", "From Parent"]
            for msg in messages:
                writer.write(f"{msg}\n")
                writer.flush()

        os.wait()

if __name__ == "__main__":
    pipe_example()
```

### 2.2 Named Pipe (FIFO)

파일 시스템에 존재하는 특수 파일로, 관련 없는 프로세스 간 통신이 가능합니다.

```
$ ls -la /tmp/myfifo
prw-r--r-- 1 user user 0 Dec 15 10:00 /tmp/myfifo
 ^
 p = FIFO (named pipe)
```

#### C 구현: 서버 (읽기)

```c
// fifo_server.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <errno.h>

#define FIFO_PATH "/tmp/my_fifo"
#define BUFFER_SIZE 1024

int main() {
    int fd;
    char buffer[BUFFER_SIZE];

    // FIFO 생성 (이미 존재하면 무시)
    if (mkfifo(FIFO_PATH, 0666) == -1) {
        if (errno != EEXIST) {
            perror("mkfifo");
            exit(EXIT_FAILURE);
        }
    }

    printf("Server: Waiting for client connection...\n");

    // 읽기 전용으로 열기 (클라이언트가 쓰기로 열 때까지 블록)
    fd = open(FIFO_PATH, O_RDONLY);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    printf("Server: Client connected!\n");

    ssize_t bytes_read;
    while ((bytes_read = read(fd, buffer, BUFFER_SIZE - 1)) > 0) {
        buffer[bytes_read] = '\0';
        printf("Server received: %s", buffer);

        if (strncmp(buffer, "quit", 4) == 0) {
            break;
        }
    }

    close(fd);
    unlink(FIFO_PATH);
    printf("Server: Shutting down.\n");

    return 0;
}
```

#### C 구현: 클라이언트 (쓰기)

```c
// fifo_client.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>

#define FIFO_PATH "/tmp/my_fifo"
#define BUFFER_SIZE 1024

int main() {
    int fd;
    char buffer[BUFFER_SIZE];

    // 쓰기 전용으로 열기
    fd = open(FIFO_PATH, O_WRONLY);
    if (fd == -1) {
        perror("open");
        printf("Is the server running?\n");
        exit(EXIT_FAILURE);
    }

    printf("Client: Connected to server!\n");
    printf("Enter messages (type 'quit' to exit):\n");

    while (fgets(buffer, BUFFER_SIZE, stdin) != NULL) {
        write(fd, buffer, strlen(buffer));

        if (strncmp(buffer, "quit", 4) == 0) {
            break;
        }
    }

    close(fd);
    printf("Client: Disconnected.\n");

    return 0;
}
```

#### Python FIFO 예제

```python
import os
import stat
import errno

FIFO_PATH = "/tmp/python_fifo"

def create_fifo():
    """FIFO 생성"""
    try:
        os.mkfifo(FIFO_PATH)
    except OSError as e:
        if e.errno != errno.EEXIST:
            raise

def server():
    """FIFO 서버 (읽기)"""
    create_fifo()
    print("Server: Waiting for connection...")

    with open(FIFO_PATH, 'r') as fifo:
        print("Server: Client connected!")
        for line in fifo:
            print(f"Received: {line.strip()}")
            if line.strip() == "quit":
                break

    os.unlink(FIFO_PATH)
    print("Server: Shutdown")

def client():
    """FIFO 클라이언트 (쓰기)"""
    with open(FIFO_PATH, 'w') as fifo:
        print("Client: Connected!")
        while True:
            message = input("Enter message: ")
            fifo.write(message + "\n")
            fifo.flush()
            if message == "quit":
                break

    print("Client: Disconnected")

if __name__ == "__main__":
    import sys
    if len(sys.argv) > 1 and sys.argv[1] == "client":
        client()
    else:
        server()
```

### 2.3 Pipe vs Named Pipe

| 특징 | Anonymous Pipe | Named Pipe (FIFO) |
|------|----------------|-------------------|
| **파일 시스템** | 없음 | 존재 (inode) |
| **프로세스 관계** | 부모-자식 필수 | 무관한 프로세스 가능 |
| **생성** | `pipe()` | `mkfifo()` |
| **지속성** | 프로세스 종료 시 삭제 | 명시적 삭제 필요 |
| **식별** | 파일 디스크립터 | 경로명 |

