## 3. Message Queue

### 3.1 POSIX Message Queue

구조화된 메시지를 큐를 통해 비동기적으로 전달합니다.

```
Producer Process                Consumer Process
┌───────────────┐              ┌───────────────┐
│   mq_send()   │              │   mq_receive()│
└───────┬───────┘              └───────┬───────┘
        │                              │
        ▼                              ▼
   ┌─────────────────────────────────────┐
   │          Message Queue              │
   │  ┌─────┬─────┬─────┬─────┬─────┐   │
   │  │ Msg1│ Msg2│ Msg3│ ... │ MsgN│   │
   │  └─────┴─────┴─────┴─────┴─────┘   │
   │     Priority-based ordering         │
   └─────────────────────────────────────┘
                   Kernel Space
```

#### C 구현: 생산자

```c
// mq_producer.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <mqueue.h>
#include <errno.h>

#define QUEUE_NAME "/my_message_queue"
#define MAX_MSG_SIZE 256
#define MAX_MESSAGES 10

typedef struct {
    long type;
    char data[MAX_MSG_SIZE];
    int priority;
} message_t;

int main() {
    mqd_t mq;
    struct mq_attr attr;

    // 큐 속성 설정
    attr.mq_flags = 0;
    attr.mq_maxmsg = MAX_MESSAGES;
    attr.mq_msgsize = sizeof(message_t);
    attr.mq_curmsgs = 0;

    // 메시지 큐 생성/열기
    mq = mq_open(QUEUE_NAME, O_CREAT | O_WRONLY, 0644, &attr);
    if (mq == (mqd_t)-1) {
        perror("mq_open");
        exit(EXIT_FAILURE);
    }

    printf("Producer: Message queue opened.\n");

    // 메시지 전송
    for (int i = 0; i < 5; i++) {
        message_t msg;
        msg.type = 1;
        snprintf(msg.data, sizeof(msg.data), "Message #%d", i + 1);
        msg.priority = i % 3;  // 우선순위 0-2

        if (mq_send(mq, (char*)&msg, sizeof(msg), msg.priority) == -1) {
            perror("mq_send");
            exit(EXIT_FAILURE);
        }

        printf("Producer: Sent '%s' with priority %d\n", msg.data, msg.priority);
    }

    // 종료 메시지
    message_t end_msg = {.type = 0, .data = "END", .priority = 0};
    mq_send(mq, (char*)&end_msg, sizeof(end_msg), 9);  // 최고 우선순위

    mq_close(mq);
    printf("Producer: Done.\n");

    return 0;
}
```

#### C 구현: 소비자

```c
// mq_consumer.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <mqueue.h>

#define QUEUE_NAME "/my_message_queue"
#define MAX_MSG_SIZE 256

typedef struct {
    long type;
    char data[MAX_MSG_SIZE];
    int priority;
} message_t;

int main() {
    mqd_t mq;
    struct mq_attr attr;
    message_t msg;
    unsigned int priority;

    // 메시지 큐 열기
    mq = mq_open(QUEUE_NAME, O_RDONLY);
    if (mq == (mqd_t)-1) {
        perror("mq_open");
        exit(EXIT_FAILURE);
    }

    // 큐 속성 확인
    mq_getattr(mq, &attr);
    printf("Consumer: Queue has %ld messages\n", attr.mq_curmsgs);

    // 메시지 수신 (우선순위 높은 것부터)
    while (1) {
        ssize_t bytes_read = mq_receive(mq, (char*)&msg, sizeof(msg), &priority);

        if (bytes_read == -1) {
            perror("mq_receive");
            break;
        }

        printf("Consumer: Received '%s' (priority: %u)\n", msg.data, priority);

        if (strcmp(msg.data, "END") == 0) {
            break;
        }
    }

    mq_close(mq);
    mq_unlink(QUEUE_NAME);
    printf("Consumer: Done.\n");

    return 0;
}
```

