## 4. Shared Memory

### 4.1 공유 메모리 개요

가장 빠른 IPC 메커니즘으로, 프로세스들이 같은 물리 메모리 영역을 공유합니다.

```
Process A              Physical Memory            Process B
┌──────────────┐       ┌──────────────┐       ┌──────────────┐
│Virtual Memory│       │              │       │Virtual Memory│
│              │       │              │       │              │
│  0x7F000000 ─┼───────┼──► Frame N  ◄┼───────┼─ 0x7F100000  │
│  (shared)    │       │   (shared)   │       │  (shared)    │
│              │       │              │       │              │
└──────────────┘       └──────────────┘       └──────────────┘

장점: 커널 버퍼 복사 없음 → O(1) 데이터 접근
단점: 동기화 직접 구현 필요
```

### 4.2 POSIX Shared Memory

```c
// shm_writer.c - 공유 메모리에 데이터 쓰기
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <unistd.h>

#define SHM_NAME "/my_shared_memory"
#define SHM_SIZE 4096

typedef struct {
    int counter;
    char message[256];
    int ready;
} shared_data_t;

int main() {
    int fd;
    shared_data_t *shared;

    // 공유 메모리 객체 생성
    fd = shm_open(SHM_NAME, O_CREAT | O_RDWR, 0666);
    if (fd == -1) {
        perror("shm_open");
        exit(EXIT_FAILURE);
    }

    // 크기 설정
    if (ftruncate(fd, sizeof(shared_data_t)) == -1) {
        perror("ftruncate");
        exit(EXIT_FAILURE);
    }

    // 메모리 매핑
    shared = (shared_data_t*)mmap(NULL, sizeof(shared_data_t),
                                   PROT_READ | PROT_WRITE,
                                   MAP_SHARED, fd, 0);
    if (shared == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    // 데이터 초기화
    shared->counter = 0;
    shared->ready = 0;

    printf("Writer: Shared memory created at %p\n", shared);

    // 데이터 쓰기
    for (int i = 1; i <= 5; i++) {
        shared->counter = i;
        snprintf(shared->message, sizeof(shared->message),
                 "Message #%d from writer", i);
        shared->ready = 1;

        printf("Writer: Wrote counter=%d, message='%s'\n",
               shared->counter, shared->message);

        // 독자가 읽을 때까지 대기 (간단한 스핀락)
        while (shared->ready == 1) {
            usleep(1000);
        }
    }

    // 종료 신호
    shared->counter = -1;
    shared->ready = 1;

    sleep(1);  // 독자가 읽을 시간

    // 정리
    munmap(shared, sizeof(shared_data_t));
    close(fd);
    shm_unlink(SHM_NAME);

    printf("Writer: Done.\n");
    return 0;
}
```

```c
// shm_reader.c - 공유 메모리에서 데이터 읽기
#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <unistd.h>

#define SHM_NAME "/my_shared_memory"

typedef struct {
    int counter;
    char message[256];
    int ready;
} shared_data_t;

int main() {
    int fd;
    shared_data_t *shared;

    // 공유 메모리 열기
    fd = shm_open(SHM_NAME, O_RDWR, 0666);
    if (fd == -1) {
        perror("shm_open");
        printf("Is the writer running?\n");
        exit(EXIT_FAILURE);
    }

    // 메모리 매핑
    shared = (shared_data_t*)mmap(NULL, sizeof(shared_data_t),
                                   PROT_READ | PROT_WRITE,
                                   MAP_SHARED, fd, 0);
    if (shared == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    printf("Reader: Connected to shared memory at %p\n", shared);

    // 데이터 읽기
    while (1) {
        // 데이터 준비될 때까지 대기
        while (shared->ready == 0) {
            usleep(1000);
        }

        if (shared->counter == -1) {
            printf("Reader: Received termination signal.\n");
            break;
        }

        printf("Reader: Read counter=%d, message='%s'\n",
               shared->counter, shared->message);

        // 읽음 표시
        shared->ready = 0;
    }

    munmap(shared, sizeof(shared_data_t));
    close(fd);

    printf("Reader: Done.\n");
    return 0;
}
```

### 4.3 Python 공유 메모리

```python
from multiprocessing import shared_memory, Process
import numpy as np
import time

def writer_process(shm_name: str, shape: tuple):
    """공유 메모리에 데이터 쓰기"""
    # 기존 공유 메모리에 연결
    existing_shm = shared_memory.SharedMemory(name=shm_name)

    # NumPy 배열로 뷰 생성
    array = np.ndarray(shape, dtype=np.float64, buffer=existing_shm.buf)

    for i in range(5):
        array[:] = np.random.rand(*shape) * 100
        print(f"Writer: Updated array, sum = {array.sum():.2f}")
        time.sleep(1)

    # -1로 종료 신호
    array[:] = -1

    existing_shm.close()
    print("Writer: Done")

def reader_process(shm_name: str, shape: tuple):
    """공유 메모리에서 데이터 읽기"""
    time.sleep(0.5)  # Writer가 먼저 시작하도록

    existing_shm = shared_memory.SharedMemory(name=shm_name)
    array = np.ndarray(shape, dtype=np.float64, buffer=existing_shm.buf)

    while True:
        if np.all(array == -1):
            print("Reader: Received termination signal")
            break

        print(f"Reader: Array sum = {array.sum():.2f}")
        time.sleep(0.5)

    existing_shm.close()
    print("Reader: Done")

def main():
    """공유 메모리 데모"""
    shape = (10, 10)
    size = np.prod(shape) * np.float64().itemsize

    # 공유 메모리 생성
    shm = shared_memory.SharedMemory(create=True, size=size)
    print(f"Created shared memory: {shm.name}")

    # 초기화
    array = np.ndarray(shape, dtype=np.float64, buffer=shm.buf)
    array[:] = 0

    # 프로세스 생성 및 시작
    writer = Process(target=writer_process, args=(shm.name, shape))
    reader = Process(target=reader_process, args=(shm.name, shape))

    writer.start()
    reader.start()

    writer.join()
    reader.join()

    # 정리
    shm.close()
    shm.unlink()
    print("Shared memory cleaned up")

if __name__ == "__main__":
    main()
```

### 4.4 mmap을 이용한 파일 매핑

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <unistd.h>

int main() {
    const char *filepath = "/tmp/mmap_example.dat";
    const size_t filesize = 4096;

    // 파일 생성
    int fd = open(filepath, O_RDWR | O_CREAT | O_TRUNC, 0666);
    if (fd == -1) {
        perror("open");
        return 1;
    }

    // 파일 크기 설정
    ftruncate(fd, filesize);

    // 메모리 매핑
    char *mapped = (char*)mmap(NULL, filesize,
                                PROT_READ | PROT_WRITE,
                                MAP_SHARED, fd, 0);
    if (mapped == MAP_FAILED) {
        perror("mmap");
        return 1;
    }

    // 매핑된 메모리에 직접 쓰기
    strcpy(mapped, "Hello, Memory-Mapped File!");
    printf("Written: %s\n", mapped);

    // 변경 사항 동기화
    msync(mapped, filesize, MS_SYNC);

    // 정리
    munmap(mapped, filesize);
    close(fd);

    // 파일 내용 확인
    FILE *f = fopen(filepath, "r");
    char buffer[256];
    fgets(buffer, sizeof(buffer), f);
    printf("File content: %s\n", buffer);
    fclose(f);

    unlink(filepath);
    return 0;
}
