    // 소켓 생성
    sock_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (sock_fd == -1) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    // 서버 주소 설정
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(PORT);
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

    // 연결
    if (connect(sock_fd, (struct sockaddr*)&server_addr, sizeof(server_addr)) == -1) {
        perror("connect");
        exit(EXIT_FAILURE);
    }

    printf("Connected to server.\n");

    // 메시지 전송 및 수신
    while (fgets(buffer, BUFFER_SIZE, stdin) != NULL) {
        send(sock_fd, buffer, strlen(buffer), 0);

        ssize_t bytes_read = recv(sock_fd, buffer, BUFFER_SIZE - 1, 0);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0';
            printf("Echo: %s", buffer);
        }

        if (strncmp(buffer, "quit", 4) == 0) {
            break;
        }
    }

    close(sock_fd);
    printf("Disconnected.\n");
    return 0;
}
```

### 6.3 Unix Domain Socket

로컬 프로세스 간 통신에 최적화된 소켓입니다.

```c
// unix_socket_server.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <sys/un.h>

#define SOCKET_PATH "/tmp/my_unix_socket"
#define BUFFER_SIZE 256

int main() {
    int server_fd, client_fd;
    struct sockaddr_un server_addr, client_addr;
    socklen_t client_len = sizeof(client_addr);
    char buffer[BUFFER_SIZE];

    // 이전 소켓 파일 삭제
    unlink(SOCKET_PATH);

    // 소켓 생성
    server_fd = socket(AF_UNIX, SOCK_STREAM, 0);
    if (server_fd == -1) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    // 주소 설정
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sun_family = AF_UNIX;
    strncpy(server_addr.sun_path, SOCKET_PATH, sizeof(server_addr.sun_path) - 1);

    // 바인드
    if (bind(server_fd, (struct sockaddr*)&server_addr, sizeof(server_addr)) == -1) {
        perror("bind");
        exit(EXIT_FAILURE);
    }

    // 리슨
    listen(server_fd, 5);
    printf("Unix socket server listening at %s\n", SOCKET_PATH);

    // 연결 수락
    client_fd = accept(server_fd, (struct sockaddr*)&client_addr, &client_len);
    if (client_fd == -1) {
        perror("accept");
        exit(EXIT_FAILURE);
    }

    printf("Client connected.\n");

    // 통신
    ssize_t bytes_read;
    while ((bytes_read = recv(client_fd, buffer, BUFFER_SIZE - 1, 0)) > 0) {
        buffer[bytes_read] = '\0';
        printf("Received: %s", buffer);
        send(client_fd, buffer, bytes_read, 0);
    }

    close(client_fd);
    close(server_fd);
    unlink(SOCKET_PATH);

    return 0;
}
```

### 6.4 Python 소켓 서버/클라이언트

```python
import socket
import threading

def handle_client(client_socket: socket.socket, address: tuple):
    """클라이언트 처리 핸들러"""
    print(f"Connected: {address}")

    try:
        while True:
            data = client_socket.recv(1024)
            if not data:
                break

            message = data.decode('utf-8')
            print(f"Received from {address}: {message}")

            # 에코 응답
            client_socket.send(data)

            if message.strip() == 'quit':
                break

    except Exception as e:
        print(f"Error handling {address}: {e}")

    finally:
        client_socket.close()
        print(f"Disconnected: {address}")

def tcp_server(host: str = '127.0.0.1', port: int = 8080):
    """멀티스레드 TCP 서버"""
    server = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)

    server.bind((host, port))
    server.listen(5)
    print(f"Server listening on {host}:{port}")

    try:
        while True:
            client_socket, address = server.accept()
            thread = threading.Thread(
                target=handle_client,
                args=(client_socket, address)
            )
            thread.start()

    except KeyboardInterrupt:
        print("\nShutting down server...")

    finally:
        server.close()

def tcp_client(host: str = '127.0.0.1', port: int = 8080):
    """TCP 클라이언트"""
    client = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    client.connect((host, port))
    print(f"Connected to {host}:{port}")

    try:
        while True:
            message = input("Enter message: ")
            client.send(message.encode('utf-8'))

            response = client.recv(1024).decode('utf-8')
            print(f"Echo: {response}")

            if message == 'quit':
                break

    except KeyboardInterrupt:
        pass

    finally:
        client.close()
        print("Disconnected")

if __name__ == "__main__":
    import sys

    if len(sys.argv) > 1 and sys.argv[1] == 'client':
        tcp_client()
    else:
        tcp_server()
```

### 6.5 소켓 옵션

```c
#include <sys/socket.h>

// 주요 소켓 옵션

// 1. SO_REUSEADDR: TIME_WAIT 상태의 포트 재사용
int opt = 1;
setsockopt(sock, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

// 2. SO_REUSEPORT: 여러 프로세스가 같은 포트 바인드 (로드밸런싱)
setsockopt(sock, SOL_SOCKET, SO_REUSEPORT, &opt, sizeof(opt));

// 3. SO_KEEPALIVE: TCP Keepalive 활성화
setsockopt(sock, SOL_SOCKET, SO_KEEPALIVE, &opt, sizeof(opt));

// 4. SO_RCVBUF / SO_SNDBUF: 버퍼 크기 설정
int bufsize = 65536;
setsockopt(sock, SOL_SOCKET, SO_RCVBUF, &bufsize, sizeof(bufsize));
setsockopt(sock, SOL_SOCKET, SO_SNDBUF, &bufsize, sizeof(bufsize));

// 5. TCP_NODELAY: Nagle 알고리즘 비활성화 (저지연)
int flag = 1;
setsockopt(sock, IPPROTO_TCP, TCP_NODELAY, &flag, sizeof(flag));

// 6. SO_LINGER: close() 동작 제어
struct linger ling = {.l_onoff = 1, .l_linger = 30};  // 30초 대기
setsockopt(sock, SOL_SOCKET, SO_LINGER, &ling, sizeof(ling));
