## 2. Blocking vs Non-Blocking I/O

### 2.1 Blocking I/O

호출한 함수가 완료될 때까지 스레드가 대기(블록)합니다.

```
Application         Kernel          Hardware
    │                 │                │
    │   read()        │                │
    ├────────────────►│                │
    │                 │   DMA Read     │
    │   [BLOCKED]     ├───────────────►│
    │                 │                │
    │                 │◄───────────────┤
    │                 │   Data Ready   │
    │◄────────────────┤                │
    │   Data          │                │
    │                 │                │
    ▼ (계속 실행)      │                │
```

#### C 예제: Blocking I/O

```c
#include <stdio.h>
#include <unistd.h>
#include <fcntl.h>

int main() {
    char buffer[1024];
    ssize_t bytes_read;

    // Blocking read (기본값)
    printf("Waiting for input (blocking)...\n");
    bytes_read = read(STDIN_FILENO, buffer, sizeof(buffer));

    if (bytes_read > 0) {
        buffer[bytes_read] = '\0';
        printf("Read %zd bytes: %s", bytes_read, buffer);
    }

    return 0;
}
```

### 2.2 Non-Blocking I/O

호출한 함수가 즉시 반환하며, 데이터가 없으면 에러(EAGAIN/EWOULDBLOCK)를 반환합니다.

```
Application         Kernel          Hardware
    │                 │                │
    │   read()        │                │
    ├────────────────►│                │
    │◄────────────────┤ EAGAIN         │
    │   (즉시 반환)    │                │
    │                 │   DMA Read     │
    │   read()        ├───────────────►│
    ├────────────────►│                │
    │◄────────────────┤ EAGAIN         │
    │                 │◄───────────────┤
    │   read()        │   Data Ready   │
    ├────────────────►│                │
    │◄────────────────┤                │
    │   Data          │                │
    ▼                 │                │
```

#### C 예제: Non-Blocking I/O

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>

int main() {
    char buffer[1024];
    ssize_t bytes_read;

    // stdin을 Non-blocking으로 설정
    int flags = fcntl(STDIN_FILENO, F_GETFL, 0);
    fcntl(STDIN_FILENO, F_SETFL, flags | O_NONBLOCK);

    printf("Non-blocking read (polling)...\n");

    int attempts = 0;
    while (1) {
        bytes_read = read(STDIN_FILENO, buffer, sizeof(buffer));

        if (bytes_read > 0) {
            buffer[bytes_read] = '\0';
            printf("Read %zd bytes: %s", bytes_read, buffer);
            break;
        } else if (bytes_read == -1) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                // 데이터 없음 - 다른 작업 수행 가능
                printf("Attempt %d: No data available\n", ++attempts);
                usleep(500000);  // 0.5초 대기 (busy waiting 방지)
                continue;
            } else {
                perror("read");
                break;
            }
        } else {
            // EOF
            printf("EOF\n");
            break;
        }
    }

    // 원래 플래그로 복원
    fcntl(STDIN_FILENO, F_SETFL, flags);

    return 0;
}
```

### 2.3 Python 예제: Non-Blocking Socket

```python
import socket
import errno
import time

def non_blocking_client():
    """Non-blocking 소켓 클라이언트 예제"""

    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sock.setblocking(False)  # Non-blocking 모드

    try:
        sock.connect(('127.0.0.1', 8080))
    except BlockingIOError:
        # Non-blocking connect는 즉시 반환
        pass

    # 연결 완료 대기 (polling)
    while True:
        try:
            sock.send(b"Hello")
            print("Connected and sent data!")
            break
        except BlockingIOError:
            print("Connection in progress...")
            time.sleep(0.1)
        except Exception as e:
            print(f"Error: {e}")
            break

    # 응답 수신 (non-blocking)
    while True:
        try:
            data = sock.recv(1024)
            if data:
                print(f"Received: {data.decode()}")
            break
        except BlockingIOError:
            print("No data yet...")
            time.sleep(0.1)

    sock.close()

def non_blocking_server():
    """Non-blocking 소켓 서버 예제"""

    server = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    server.setblocking(False)

    server.bind(('127.0.0.1', 8080))
    server.listen(5)
    print("Server listening (non-blocking)...")

    clients = []

    while True:
        # 새 연결 수락 시도
        try:
            client, addr = server.accept()
            client.setblocking(False)
            clients.append(client)
            print(f"New connection from {addr}")
        except BlockingIOError:
            pass  # 새 연결 없음

        # 기존 클라이언트 처리
        for client in clients[:]:
            try:
                data = client.recv(1024)
                if data:
                    print(f"Received: {data.decode()}")
                    client.send(data)  # Echo
                else:
                    # 연결 종료
                    clients.remove(client)
                    client.close()
            except BlockingIOError:
                pass  # 데이터 없음

        time.sleep(0.01)  # CPU 사용률 감소

if __name__ == "__main__":
    import sys
    if len(sys.argv) > 1 and sys.argv[1] == 'client':
        non_blocking_client()
    else:
        non_blocking_server()
```

### 2.4 Blocking vs Non-Blocking 비교

| 특성 | Blocking | Non-Blocking |
|------|----------|--------------|
| **호출 반환** | 완료 후 | 즉시 |
| **CPU 사용** | 대기 중 유휴 | Polling 시 CPU 사용 |
| **프로그래밍 복잡도** | 간단 | 복잡 |
| **동시성** | 멀티스레드 필요 | 단일 스레드 가능 |
| **적합한 경우** | 간단한 I/O | 다중 I/O 처리 |

