## 4. I/O Multiplexing

### 4.1 I/O Multiplexing 개념

하나의 스레드로 여러 I/O 작업을 동시에 처리합니다.

```
전통적 방식 (Thread per Connection):
┌──────────────┐
│   Thread 1   │ ─── Client 1
├──────────────┤
│   Thread 2   │ ─── Client 2
├──────────────┤
│   Thread 3   │ ─── Client 3
└──────────────┘
문제: 스레드 생성 비용, 컨텍스트 스위칭, 메모리 사용

I/O Multiplexing:
┌──────────────┐
│              │ ─── Client 1
│  Single      │ ─── Client 2
│  Thread      │ ─── Client 3
│              │ ─── Client 4
└──────────────┘
     │
     ▼
┌──────────────┐
│ select/poll  │
│ epoll/kqueue │
└──────────────┘
```

### 4.2 select()

가장 오래된 I/O Multiplexing 메커니즘입니다.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/select.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <errno.h>

#define PORT 8080
#define MAX_CLIENTS 10
#define BUFFER_SIZE 1024

int main() {
    int server_fd, client_fds[MAX_CLIENTS];
    fd_set read_fds, master_fds;
    int max_fd;
    struct sockaddr_in server_addr;
    char buffer[BUFFER_SIZE];

    // 클라이언트 배열 초기화
    for (int i = 0; i < MAX_CLIENTS; i++) {
        client_fds[i] = -1;
    }

    // 서버 소켓 생성
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    bind(server_fd, (struct sockaddr*)&server_addr, sizeof(server_addr));
    listen(server_fd, MAX_CLIENTS);

    printf("Server listening on port %d (using select)\n", PORT);

    // fd_set 초기화
    FD_ZERO(&master_fds);
    FD_SET(server_fd, &master_fds);
    max_fd = server_fd;

    while (1) {
        read_fds = master_fds;  // select가 수정하므로 복사

        // I/O 이벤트 대기
        int activity = select(max_fd + 1, &read_fds, NULL, NULL, NULL);

        if (activity < 0 && errno != EINTR) {
            perror("select");
            break;
        }

        // 새 연결 확인
        if (FD_ISSET(server_fd, &read_fds)) {
            struct sockaddr_in client_addr;
            socklen_t client_len = sizeof(client_addr);
            int new_fd = accept(server_fd, (struct sockaddr*)&client_addr, &client_len);

            if (new_fd >= 0) {
                printf("New connection: fd=%d\n", new_fd);

                // 클라이언트 배열에 추가
                for (int i = 0; i < MAX_CLIENTS; i++) {
                    if (client_fds[i] == -1) {
                        client_fds[i] = new_fd;
                        FD_SET(new_fd, &master_fds);
                        if (new_fd > max_fd) max_fd = new_fd;
                        break;
                    }
                }
            }
        }

        // 클라이언트 이벤트 처리
        for (int i = 0; i < MAX_CLIENTS; i++) {
            int fd = client_fds[i];
            if (fd == -1) continue;

            if (FD_ISSET(fd, &read_fds)) {
                ssize_t bytes = read(fd, buffer, BUFFER_SIZE - 1);

                if (bytes <= 0) {
                    // 연결 종료 또는 에러
                    printf("Client disconnected: fd=%d\n", fd);
                    close(fd);
                    FD_CLR(fd, &master_fds);
                    client_fds[i] = -1;
                } else {
                    buffer[bytes] = '\0';
                    printf("Received from fd=%d: %s", fd, buffer);

                    // Echo
                    write(fd, buffer, bytes);
                }
            }
        }
    }

    close(server_fd);
    return 0;
}
```

#### select() 한계

- **FD 개수 제한**: FD_SETSIZE (보통 1024)
- **매번 fd_set 복사**: O(n) 복잡도
- **선형 검색**: 어떤 fd가 ready인지 확인하려면 전체 순회

### 4.3 poll()

select의 FD 개수 제한을 해결합니다.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <poll.h>
#include <sys/socket.h>
#include <netinet/in.h>

#define PORT 8080
#define MAX_CLIENTS 1000
#define BUFFER_SIZE 1024

int main() {
    int server_fd;
    struct pollfd fds[MAX_CLIENTS + 1];
    int nfds = 1;
    struct sockaddr_in server_addr;
    char buffer[BUFFER_SIZE];

    // 서버 소켓 생성 및 설정
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    bind(server_fd, (struct sockaddr*)&server_addr, sizeof(server_addr));
    listen(server_fd, MAX_CLIENTS);

    printf("Server listening on port %d (using poll)\n", PORT);

    // pollfd 배열 초기화
    fds[0].fd = server_fd;
    fds[0].events = POLLIN;

    while (1) {
        int activity = poll(fds, nfds, -1);  // 무한 대기

        if (activity < 0) {
            perror("poll");
            break;
        }

        // 새 연결 확인
        if (fds[0].revents & POLLIN) {
            struct sockaddr_in client_addr;
            socklen_t client_len = sizeof(client_addr);
            int new_fd = accept(server_fd, (struct sockaddr*)&client_addr, &client_len);

            if (new_fd >= 0 && nfds < MAX_CLIENTS + 1) {
                printf("New connection: fd=%d\n", new_fd);
                fds[nfds].fd = new_fd;
                fds[nfds].events = POLLIN;
                nfds++;
            }
        }

        // 클라이언트 이벤트 처리
        for (int i = 1; i < nfds; i++) {
            if (fds[i].revents & POLLIN) {
                ssize_t bytes = read(fds[i].fd, buffer, BUFFER_SIZE - 1);

                if (bytes <= 0) {
                    printf("Client disconnected: fd=%d\n", fds[i].fd);
                    close(fds[i].fd);

                    // 배열 압축
                    fds[i] = fds[nfds - 1];
                    nfds--;
                    i--;  // 현재 위치 다시 확인
                } else {
                    buffer[bytes] = '\0';
                    printf("Received from fd=%d: %s", fds[i].fd, buffer);
                    write(fds[i].fd, buffer, bytes);
                }
            }
        }
    }

    close(server_fd);
    return 0;
}
```

### 4.4 epoll (Linux)

Linux의 고성능 I/O Multiplexing 메커니즘입니다.

```
epoll 구조:

User Space                    Kernel Space
┌──────────────┐             ┌──────────────────────────┐
│              │             │                          │
│ epoll_create ├────────────►│   epoll instance         │
│              │             │   ┌──────────────────┐   │
│ epoll_ctl    ├────────────►│   │  Red-Black Tree  │   │
│ (ADD/MOD/DEL)│             │   │  (관심 FD 목록)   │   │
│              │             │   └──────────────────┘   │
│ epoll_wait   │◄────────────┤   ┌──────────────────┐   │
│              │             │   │  Ready List      │   │
│              │             │   │  (이벤트 발생 FD) │   │
│              │             │   └──────────────────┘   │
└──────────────┘             └──────────────────────────┘

특징:
- O(1) 이벤트 알림 (Ready List 반환)
- FD 개수 제한 없음
- Edge/Level Triggered 모드 지원
```

#### epoll 예제

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/epoll.h>
#include <sys/socket.h>
#include <netinet/in.h>

#define PORT 8080
#define MAX_EVENTS 100
#define BUFFER_SIZE 1024

// Non-blocking 설정
void set_nonblocking(int fd) {
    int flags = fcntl(fd, F_GETFL, 0);
    fcntl(fd, F_SETFL, flags | O_NONBLOCK);
}

int main() {
    int server_fd, epoll_fd;
    struct epoll_event ev, events[MAX_EVENTS];
    struct sockaddr_in server_addr;
    char buffer[BUFFER_SIZE];

    // 서버 소켓 생성
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));
    set_nonblocking(server_fd);

    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    bind(server_fd, (struct sockaddr*)&server_addr, sizeof(server_addr));
    listen(server_fd, SOMAXCONN);

    printf("Server listening on port %d (using epoll)\n", PORT);

    // epoll 인스턴스 생성
    epoll_fd = epoll_create1(0);
    if (epoll_fd == -1) {
        perror("epoll_create1");
        exit(EXIT_FAILURE);
    }

    // 서버 소켓 등록
    ev.events = EPOLLIN;
    ev.data.fd = server_fd;
    epoll_ctl(epoll_fd, EPOLL_CTL_ADD, server_fd, &ev);

    while (1) {
        int nfds = epoll_wait(epoll_fd, events, MAX_EVENTS, -1);

        if (nfds == -1) {
            if (errno == EINTR) continue;
            perror("epoll_wait");
            break;
        }

        for (int i = 0; i < nfds; i++) {
            int fd = events[i].data.fd;

            if (fd == server_fd) {
                // 새 연결
                while (1) {
                    struct sockaddr_in client_addr;
                    socklen_t client_len = sizeof(client_addr);
                    int client_fd = accept(server_fd,
                                           (struct sockaddr*)&client_addr,
                                           &client_len);

                    if (client_fd == -1) {
                        if (errno == EAGAIN || errno == EWOULDBLOCK) {
                            break;  // 모든 연결 처리됨
                        }
                        perror("accept");
                        break;
                    }

                    printf("New connection: fd=%d\n", client_fd);
                    set_nonblocking(client_fd);

                    // Edge Triggered 모드로 등록
                    ev.events = EPOLLIN | EPOLLET;
                    ev.data.fd = client_fd;
                    epoll_ctl(epoll_fd, EPOLL_CTL_ADD, client_fd, &ev);
                }

            } else if (events[i].events & EPOLLIN) {
                // 데이터 수신 (Edge Triggered이므로 모두 읽어야 함)
                while (1) {
                    ssize_t bytes = read(fd, buffer, BUFFER_SIZE - 1);

                    if (bytes <= 0) {
                        if (bytes == 0 || (errno != EAGAIN && errno != EWOULDBLOCK)) {
                            printf("Client disconnected: fd=%d\n", fd);
                            epoll_ctl(epoll_fd, EPOLL_CTL_DEL, fd, NULL);
                            close(fd);
                        }
                        break;
                    }

                    buffer[bytes] = '\0';
                    printf("Received from fd=%d: %s", fd, buffer);
                    write(fd, buffer, bytes);  // Echo
                }
            }
        }
    }

    close(epoll_fd);
    close(server_fd);
    return 0;
}
```

### 4.5 kqueue (BSD/macOS)

BSD 계열 시스템의 고성능 I/O Multiplexing입니다.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/event.h>
#include <sys/socket.h>
#include <netinet/in.h>

#define PORT 8080
#define MAX_EVENTS 100
#define BUFFER_SIZE 1024

void set_nonblocking(int fd) {
    int flags = fcntl(fd, F_GETFL, 0);
    fcntl(fd, F_SETFL, flags | O_NONBLOCK);
}

int main() {
    int server_fd, kq;
    struct kevent change_event, events[MAX_EVENTS];
    struct sockaddr_in server_addr;
    char buffer[BUFFER_SIZE];

    // 서버 소켓 생성
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));
    set_nonblocking(server_fd);

    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    bind(server_fd, (struct sockaddr*)&server_addr, sizeof(server_addr));
    listen(server_fd, SOMAXCONN);

    printf("Server listening on port %d (using kqueue)\n", PORT);

    // kqueue 생성
    kq = kqueue();
    if (kq == -1) {
        perror("kqueue");
        exit(EXIT_FAILURE);
    }

    // 서버 소켓 등록
    EV_SET(&change_event, server_fd, EVFILT_READ, EV_ADD | EV_ENABLE, 0, 0, NULL);
    kevent(kq, &change_event, 1, NULL, 0, NULL);

    while (1) {
        int nev = kevent(kq, NULL, 0, events, MAX_EVENTS, NULL);

        if (nev == -1) {
            perror("kevent");
            break;
        }

        for (int i = 0; i < nev; i++) {
            int fd = (int)events[i].ident;

            if (events[i].flags & EV_EOF) {
                printf("Client disconnected: fd=%d\n", fd);
                close(fd);
                continue;
            }

            if (fd == server_fd) {
                // 새 연결
                struct sockaddr_in client_addr;
                socklen_t client_len = sizeof(client_addr);
                int client_fd = accept(server_fd,
                                       (struct sockaddr*)&client_addr,
                                       &client_len);

                if (client_fd >= 0) {
                    printf("New connection: fd=%d\n", client_fd);
                    set_nonblocking(client_fd);

                    EV_SET(&change_event, client_fd, EVFILT_READ,
                           EV_ADD | EV_ENABLE, 0, 0, NULL);
                    kevent(kq, &change_event, 1, NULL, 0, NULL);
                }

            } else if (events[i].filter == EVFILT_READ) {
                // 데이터 수신
                ssize_t bytes = read(fd, buffer, BUFFER_SIZE - 1);

                if (bytes > 0) {
                    buffer[bytes] = '\0';
                    printf("Received from fd=%d: %s", fd, buffer);
                    write(fd, buffer, bytes);
                } else {
                    close(fd);
                }
            }
        }
    }

    close(kq);
    close(server_fd);
    return 0;
}
```

### 4.6 I/O Multiplexing 비교

| 특성 | select | poll | epoll | kqueue |
|------|--------|------|-------|--------|
| **FD 제한** | FD_SETSIZE (1024) | 없음 | 없음 | 없음 |
| **이벤트 전달** | 전체 복사 | 전체 복사 | Ready List만 | Ready List만 |
| **복잡도** | O(n) | O(n) | O(1) | O(1) |
| **Edge Trigger** | 없음 | 없음 | 지원 | 지원 |
| **지원 OS** | 모든 POSIX | 모든 POSIX | Linux | BSD/macOS |

### 4.7 Python selectors 모듈

```python
import selectors
import socket

def create_server_socket(host: str, port: int) -> socket.socket:
    """서버 소켓 생성"""
    server = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    server.setblocking(False)
    server.bind((host, port))
    server.listen(100)
    return server

def accept_connection(sel: selectors.BaseSelector, server: socket.socket):
    """새 연결 수락"""
    client, addr = server.accept()
    print(f"New connection from {addr}")
    client.setblocking(False)
    sel.register(client, selectors.EVENT_READ, handle_client)

def handle_client(sel: selectors.BaseSelector, client: socket.socket):
    """클라이언트 데이터 처리"""
    try:
        data = client.recv(1024)
        if data:
            print(f"Received: {data.decode()}")
            client.send(data)  # Echo
        else:
            print("Client disconnected")
            sel.unregister(client)
            client.close()
    except Exception as e:
        print(f"Error: {e}")
        sel.unregister(client)
        client.close()

def main():
    """I/O Multiplexing 서버 (selectors 모듈 사용)"""

    # 최적의 selector 자동 선택 (epoll, kqueue, select 중)
    sel = selectors.DefaultSelector()
    print(f"Using selector: {type(sel).__name__}")

    server = create_server_socket('127.0.0.1', 8080)
    sel.register(server, selectors.EVENT_READ, accept_connection)
    print("Server listening on port 8080")

    try:
        while True:
            events = sel.select(timeout=None)

            for key, mask in events:
                callback = key.data
                if callback == accept_connection:
                    accept_connection(sel, key.fileobj)
                else:
                    handle_client(sel, key.fileobj)

    except KeyboardInterrupt:
        print("\nShutting down...")

    finally:
        sel.close()
        server.close()

if __name__ == "__main__":
    main()
```

### 4.8 Edge Trigger vs Level Trigger

```
Level Triggered (기본):
- 조건이 만족되는 동안 계속 알림
- 읽을 데이터가 있으면 epoll_wait이 계속 반환
- 놓치기 어려움, 구현 간단

Edge Triggered (EPOLLET):
- 상태 변화 시에만 알림
- 새 데이터가 도착했을 때만 알림
- 반드시 모든 데이터를 읽어야 함 (EAGAIN까지)
- 성능 향상, 구현 복잡

예시:
  100 bytes 도착

Level Triggered:
  epoll_wait() → returns (50 bytes 읽음)
  epoll_wait() → returns (50 bytes 남음)
  epoll_wait() → returns (데이터 있으면)

Edge Triggered:
  epoll_wait() → returns (한 번만!)
  read() until EAGAIN
```

