### 3.4 프로세스 대기

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>

void wait_demo() {
    // 여러 자식 생성
    for (int i = 0; i < 3; i++) {
        pid_t pid = fork();

        if (pid == 0) {
            // 자식
            printf("Child %d (PID=%d) starting\n", i, getpid());
            sleep(i + 1);
            printf("Child %d exiting with code %d\n", i, i * 10);
            exit(i * 10);
        }
    }

    // 부모: 모든 자식 대기
    int status;
    pid_t pid;

    // wait(): 아무 자식이나 종료될 때까지 대기
    // waitpid(): 특정 자식 대기 가능

    while ((pid = wait(&status)) > 0) {
        if (WIFEXITED(status)) {
            printf("Child %d exited with status %d\n",
                   pid, WEXITSTATUS(status));
        } else if (WIFSIGNALED(status)) {
            printf("Child %d killed by signal %d\n",
                   pid, WTERMSIG(status));
        } else if (WIFSTOPPED(status)) {
            printf("Child %d stopped by signal %d\n",
                   pid, WSTOPSIG(status));
        }
    }

    printf("All children terminated\n");
}

void waitpid_options_demo() {
    pid_t pid = fork();

    if (pid == 0) {
        sleep(3);
        exit(0);
    }

    // WNOHANG: Non-blocking 대기
    int status;
    pid_t result;

    while (1) {
        result = waitpid(pid, &status, WNOHANG);

        if (result == 0) {
            printf("Child still running...\n");
            sleep(1);
        } else if (result > 0) {
            printf("Child exited\n");
            break;
        } else {
            perror("waitpid");
            break;
        }
    }
}

int main() {
    printf("=== wait() demo ===\n");
    wait_demo();

    printf("\n=== waitpid() with WNOHANG ===\n");
    waitpid_options_demo();

    return 0;
}
```

