### 4.6 시그널 전송

```c
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <sys/wait.h>

void kill_demo() {
    pid_t pid = fork();

    if (pid == 0) {
        // 자식: 시그널 대기
        printf("Child: PID=%d, waiting for signals...\n", getpid());

        while (1) {
            pause();  // 시그널 대기
        }
    } else {
        // 부모: 시그널 전송
        sleep(1);

        // SIGUSR1 전송
        printf("Parent: Sending SIGUSR1 to child\n");
        kill(pid, SIGUSR1);
        sleep(1);

        // SIGTERM 전송
        printf("Parent: Sending SIGTERM to child\n");
        kill(pid, SIGTERM);

        waitpid(pid, NULL, 0);
        printf("Parent: Child terminated\n");
    }
}

void raise_demo() {
    printf("Raising SIGINT to myself...\n");
    raise(SIGINT);  // 자신에게 시그널 전송
    printf("This won't be printed (default SIGINT handler)\n");
}

void alarm_demo() {
    signal(SIGALRM, signal_handler);

    printf("Setting alarm for 3 seconds...\n");
    alarm(3);

    printf("Waiting...\n");
    pause();  // 시그널 대기

    printf("Alarm received!\n");
}
```

