# 4. 최장 증가 부분 수열 (LIS)
# O(n²) 풀이
def lis_n2(arr):
    n = len(arr)
    dp = [1] * n  # dp[i] = arr[i]로 끝나는 LIS 길이

    for i in range(1, n):
        for j in range(i):
            if arr[j] < arr[i]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

# O(n log n) 풀이 - 이진 탐색 활용
import bisect

def lis_nlogn(arr):
    tails = []  # tails[i] = 길이 i+1인 증가 수열의 마지막 원소 최솟값

    for num in arr:
        idx = bisect.bisect_left(tails, num)
        if idx == len(tails):
            tails.append(num)
        else:
            tails[idx] = num

    return len(tails)
