# 클로저: 함수가 정의된 환경(스코프)을 기억

def make_counter():
    count = 0  # 자유 변수 (free variable)

    def counter():
        nonlocal count  # 외부 변수 참조
        count += 1
        return count

    return counter

counter1 = make_counter()
counter2 = make_counter()

print(counter1())  # 1
print(counter1())  # 2
print(counter2())  # 1 (독립적인 환경)
