### 7.3 함수형 상태 관리 (Redux 스타일)

```javascript
// JavaScript - 함수형 상태 관리
const initialState = {
    count: 0,
    items: [],
    loading: false
};

// 순수 함수인 리듀서
const reducer = (state = initialState, action) => {
    switch (action.type) {
        case 'INCREMENT':
            return { ...state, count: state.count + 1 };

        case 'DECREMENT':
            return { ...state, count: state.count - 1 };

        case 'ADD_ITEM':
            return {
                ...state,
                items: [...state.items, action.payload]
            };

        case 'REMOVE_ITEM':
            return {
                ...state,
                items: state.items.filter(item => item.id !== action.payload)
            };

        case 'SET_LOADING':
            return { ...state, loading: action.payload };

        default:
            return state;
    }
};

// 불변성 유지 - immer 라이브러리 활용
import produce from 'immer';

const reducerWithImmer = (state = initialState, action) => {
    return produce(state, draft => {
        switch (action.type) {
            case 'INCREMENT':
                draft.count += 1;
                break;
            case 'ADD_ITEM':
                draft.items.push(action.payload);
                break;
            case 'REMOVE_ITEM':
                const index = draft.items.findIndex(i => i.id === action.payload);
                if (index !== -1) draft.items.splice(index, 1);
                break;
        }
    });
};
