## 데이터 모델링

### 임베딩 vs 참조

```javascript
// 1. 임베딩 (Embedded) - 1:N 관계에서 N이 작을 때
// 장점: 단일 쿼리로 모든 데이터 조회
// 단점: 문서 크기 제한 (16MB), 중첩 데이터 수정 복잡

// 블로그 포스트와 댓글 (댓글이 적을 때)
{
    _id: ObjectId("..."),
    title: "MongoDB 튜토리얼",
    content: "...",
    author: "kim",
    comments: [
        { user: "lee", text: "좋아요!", date: ISODate("...") },
        { user: "park", text: "감사합니다", date: ISODate("...") }
    ]
}

// 2. 참조 (Reference) - 1:N 관계에서 N이 크거나 독립적일 때
// 장점: 데이터 중복 없음, 대용량 데이터 처리
// 단점: 조인 필요 ($lookup)

// posts 컬렉션
{
    _id: ObjectId("post1"),
    title: "MongoDB 튜토리얼",
    content: "...",
    author_id: ObjectId("user1")
}

// comments 컬렉션
{
    _id: ObjectId("comment1"),
    post_id: ObjectId("post1"),
    user: "lee",
    text: "좋아요!",
    date: ISODate("...")
}

// $lookup으로 조인
db.posts.aggregate([
    {
        $lookup: {
            from: "comments",
            localField: "_id",
            foreignField: "post_id",
            as: "comments"
        }
    }
]);
```

### 모델링 패턴

```javascript
// 1. Extended Reference Pattern - 자주 접근하는 필드 복제
// orders 컬렉션
{
    _id: ObjectId("..."),
    customer_id: ObjectId("customer1"),
    // 자주 필요한 고객 정보만 복제
    customer_name: "김철수",
    customer_email: "kim@example.com",
    items: [...]
}

// 2. Subset Pattern - 일부 데이터만 임베딩
// 최근 리뷰 5개만 제품에 임베딩
{
    _id: ObjectId("..."),
    name: "MacBook Pro",
    price: 2000000,
    recent_reviews: [
        // 최근 5개만
    ]
}
// 전체 리뷰는 별도 컬렉션에 저장

// 3. Bucket Pattern - 시계열 데이터 그룹화
// 1시간 단위로 센서 데이터 버킷팅
{
    sensor_id: "sensor_001",
    start_time: ISODate("2024-01-01T00:00:00Z"),
    end_time: ISODate("2024-01-01T01:00:00Z"),
    measurements: [
        { time: ISODate("2024-01-01T00:00:00Z"), value: 25.1 },
        { time: ISODate("2024-01-01T00:01:00Z"), value: 25.2 },
        // ... 60개의 측정값
    ],
    count: 60,
    sum: 1510.5,
    avg: 25.175
}

// 4. Computed Pattern - 계산 결과 미리 저장
{
    _id: ObjectId("..."),
    title: "MongoDB 입문",
    ratings: [5, 4, 5, 3, 5],
    // 미리 계산된 집계 값
    rating_count: 5,
    rating_sum: 22,
    rating_avg: 4.4
}
```

