## 집계 파이프라인

### 기본 집계 연산자

```javascript
// 파이프라인 예시: 월별 매출 분석
db.orders.aggregate([
    // 1. 필터링
    { $match: { status: "completed", order_date: { $gte: ISODate("2024-01-01") } } },

    // 2. 필드 추가/변환
    { $addFields: {
        month: { $month: "$order_date" },
        revenue: { $multiply: ["$quantity", "$price"] }
    }},

    // 3. 그룹화
    { $group: {
        _id: "$month",
        totalRevenue: { $sum: "$revenue" },
        orderCount: { $sum: 1 },
        avgOrderValue: { $avg: "$revenue" }
    }},

    // 4. 정렬
    { $sort: { _id: 1 } },

    // 5. 출력 형식
    { $project: {
        month: "$_id",
        totalRevenue: { $round: ["$totalRevenue", 2] },
        orderCount: 1,
        avgOrderValue: { $round: ["$avgOrderValue", 2] }
    }}
]);
```

### 고급 집계 연산

```javascript
// $lookup (조인)
db.orders.aggregate([
    {
        $lookup: {
            from: "customers",
            localField: "customer_id",
            foreignField: "_id",
            as: "customer"
        }
    },
    { $unwind: "$customer" }  // 배열을 개별 문서로
]);

// $facet (다중 집계)
db.products.aggregate([
    {
        $facet: {
            "byCategory": [
                { $group: { _id: "$category", count: { $sum: 1 } } }
            ],
            "priceRanges": [
                { $bucket: {
                    groupBy: "$price",
                    boundaries: [0, 100, 500, 1000, Infinity],
                    output: { count: { $sum: 1 } }
                }}
            ],
            "topProducts": [
                { $sort: { sales: -1 } },
                { $limit: 5 }
            ]
        }
    }
]);

// $graphLookup (재귀적 조회)
db.employees.aggregate([
    { $match: { name: "CEO" } },
    {
        $graphLookup: {
            from: "employees",
            startWith: "$_id",
            connectFromField: "_id",
            connectToField: "manager_id",
            as: "allReports",
            maxDepth: 5
        }
    }
]);

// $merge (결과를 다른 컬렉션에 저장)
db.orders.aggregate([
    { $group: { _id: "$customer_id", totalSpent: { $sum: "$amount" } } },
    { $merge: {
        into: "customer_stats",
        on: "_id",
        whenMatched: "merge",
        whenNotMatched: "insert"
    }}
]);
```

