### 서비스 정의

```protobuf
// user_service.proto
syntax = "proto3";

package user.v1;

import "google/protobuf/empty.proto";
import "google/protobuf/field_mask.proto";

service UserService {
  // Unary RPC
  rpc GetUser(GetUserRequest) returns (User);
  rpc CreateUser(CreateUserRequest) returns (User);

  // Server Streaming
  rpc ListUsers(ListUsersRequest) returns (stream User);

  // Client Streaming
  rpc BatchCreateUsers(stream CreateUserRequest) returns (BatchCreateUsersResponse);

  // Bidirectional Streaming
  rpc Chat(stream ChatMessage) returns (stream ChatMessage);

  // 업데이트 (Partial Update with FieldMask)
  rpc UpdateUser(UpdateUserRequest) returns (User);

  // 삭제
  rpc DeleteUser(DeleteUserRequest) returns (google.protobuf.Empty);
}

message GetUserRequest {
  int64 id = 1;
}

message CreateUserRequest {
  string name = 1;
  string email = 2;
}

message ListUsersRequest {
  int32 page_size = 1;
  string page_token = 2;
  string filter = 3;  // e.g., "status=ACTIVE"
}

message UpdateUserRequest {
  User user = 1;
  google.protobuf.FieldMask update_mask = 2;  // 업데이트할 필드 지정
}

message DeleteUserRequest {
  int64 id = 1;
}

message BatchCreateUsersResponse {
  repeated User users = 1;
  int32 created_count = 2;
}

message ChatMessage {
  string user_id = 1;
  string content = 2;
  int64 timestamp = 3;
}
```

### 필드 번호 규칙

```protobuf
message FieldNumberRules {
  // 1-15: 1바이트로 인코딩 (자주 사용하는 필드에 할당)
  int64 id = 1;
  string name = 2;

  // 16-2047: 2바이트로 인코딩
  string description = 16;

  // 19000-19999: 예약됨 (사용 불가)

  // 필드 번호 예약 (하위 호환성)
  reserved 4, 5, 100 to 200;
  reserved "old_field", "deprecated_field";
}
```

