## 인터셉터 (Interceptor)

인터셉터는 gRPC의 미들웨어로, 요청/응답 처리 전후에 로직을 추가합니다.

### 인터셉터 타입

```
┌─────────────────────────────────────────────────────────┐
│                    Interceptor Types                     │
├─────────────────────────────────────────────────────────┤
│  Server Side                                            │
│  ├── UnaryServerInterceptor    (단항 RPC용)              │
│  └── StreamServerInterceptor   (스트리밍 RPC용)          │
│                                                         │
│  Client Side                                            │
│  ├── UnaryClientInterceptor    (단항 RPC용)              │
│  └── StreamClientInterceptor   (스트리밍 RPC용)          │
└─────────────────────────────────────────────────────────┘
```

### Unary 인터셉터 구현

```go
// 서버 사이드 - 로깅 인터셉터
func loggingUnaryInterceptor(
    ctx context.Context,
    req interface{},
    info *grpc.UnaryServerInfo,
    handler grpc.UnaryHandler,
) (interface{}, error) {
    start := time.Now()

    // 핸들러 실행 (실제 RPC 호출)
    resp, err := handler(ctx, req)

    // 로깅
    duration := time.Since(start)
    log.Printf(
        "method=%s duration=%v err=%v",
        info.FullMethod,
        duration,
        err,
    )

    return resp, err
}

// 서버 사이드 - 인증 인터셉터
func authUnaryInterceptor(
    ctx context.Context,
    req interface{},
    info *grpc.UnaryServerInfo,
    handler grpc.UnaryHandler,
) (interface{}, error) {
    // 메타데이터에서 토큰 추출
    md, ok := metadata.FromIncomingContext(ctx)
    if !ok {
        return nil, status.Error(codes.Unauthenticated, "missing metadata")
    }

    tokens := md.Get("authorization")
    if len(tokens) == 0 {
        return nil, status.Error(codes.Unauthenticated, "missing token")
    }

    token := strings.TrimPrefix(tokens[0], "Bearer ")

    // 토큰 검증
    user, err := validateToken(token)
    if err != nil {
        return nil, status.Error(codes.Unauthenticated, "invalid token")
    }

    // 컨텍스트에 사용자 정보 추가
    ctx = context.WithValue(ctx, userContextKey, user)

    return handler(ctx, req)
}

// 서버 사이드 - 복구 인터셉터 (패닉 처리)
func recoveryUnaryInterceptor(
    ctx context.Context,
    req interface{},
    info *grpc.UnaryServerInfo,
    handler grpc.UnaryHandler,
) (resp interface{}, err error) {
    defer func() {
        if r := recover(); r != nil {
            log.Printf("panic recovered: %v\nstack: %s", r, debug.Stack())
            err = status.Errorf(codes.Internal, "internal error")
        }
    }()

    return handler(ctx, req)
}
```

### Stream 인터셉터 구현

```go
// 서버 스트림 인터셉터
func loggingStreamInterceptor(
    srv interface{},
    ss grpc.ServerStream,
    info *grpc.StreamServerInfo,
    handler grpc.StreamHandler,
) error {
    start := time.Now()

    // 래핑된 스트림으로 메시지 로깅
    wrappedStream := &loggingServerStream{ServerStream: ss}

    err := handler(srv, wrappedStream)

    log.Printf(
        "stream method=%s duration=%v sent=%d received=%d err=%v",
        info.FullMethod,
        time.Since(start),
        wrappedStream.sentCount,
        wrappedStream.receivedCount,
        err,
    )

    return err
}

type loggingServerStream struct {
    grpc.ServerStream
    sentCount     int
    receivedCount int
}

func (s *loggingServerStream) SendMsg(m interface{}) error {
    s.sentCount++
    return s.ServerStream.SendMsg(m)
}

func (s *loggingServerStream) RecvMsg(m interface{}) error {
    err := s.ServerStream.RecvMsg(m)
    if err == nil {
        s.receivedCount++
    }
    return err
}
```

### 클라이언트 인터셉터

```go
// 클라이언트 - 재시도 인터셉터
func retryUnaryInterceptor(
    ctx context.Context,
    method string,
    req, reply interface{},
    cc *grpc.ClientConn,
    invoker grpc.UnaryInvoker,
    opts ...grpc.CallOption,
) error {
    maxRetries := 3
    backoff := 100 * time.Millisecond

    var lastErr error
    for i := 0; i < maxRetries; i++ {
        err := invoker(ctx, method, req, reply, cc, opts...)
        if err == nil {
            return nil
        }

        // 재시도 가능한 에러인지 확인
        code := status.Code(err)
        if code != codes.Unavailable && code != codes.DeadlineExceeded {
            return err
        }

        lastErr = err
        log.Printf("Retry %d/%d for %s: %v", i+1, maxRetries, method, err)

        select {
        case <-ctx.Done():
            return ctx.Err()
        case <-time.After(backoff):
            backoff *= 2  // 지수 백오프
        }
    }

    return lastErr
}

// 클라이언트 - 메타데이터 추가 인터셉터
func metadataUnaryInterceptor(
    ctx context.Context,
    method string,
    req, reply interface{},
    cc *grpc.ClientConn,
    invoker grpc.UnaryInvoker,
    opts ...grpc.CallOption,
) error {
    // 메타데이터 추가
    md := metadata.Pairs(
        "x-request-id", uuid.New().String(),
        "x-client-version", "1.0.0",
    )
    ctx = metadata.NewOutgoingContext(ctx, md)

    return invoker(ctx, method, req, reply, cc, opts...)
}
```

### 인터셉터 체이닝

```go
import "google.golang.org/grpc/middleware"

// 서버에 여러 인터셉터 적용
server := grpc.NewServer(
    grpc.ChainUnaryInterceptor(
        recoveryUnaryInterceptor,  // 가장 바깥쪽 (먼저 실행)
        loggingUnaryInterceptor,
        authUnaryInterceptor,
        rateLimitUnaryInterceptor,
    ),
    grpc.ChainStreamInterceptor(
        recoveryStreamInterceptor,
        loggingStreamInterceptor,
        authStreamInterceptor,
    ),
)

// 클라이언트에 인터셉터 적용
conn, err := grpc.Dial(
    address,
    grpc.WithTransportCredentials(insecure.NewCredentials()),
    grpc.WithChainUnaryInterceptor(
        metadataUnaryInterceptor,
        retryUnaryInterceptor,
        loggingClientInterceptor,
    ),
)
```

