## 하트비트와 재연결

### 하트비트 (Keep-Alive)

네트워크 연결 상태를 확인하고 유지하기 위한 메커니즘:

```
┌─────────────────────────────────────────────────────────┐
│                    Heartbeat Flow                        │
├─────────────────────────────────────────────────────────┤
│ Server                           Client                  │
│   │                                 │                    │
│   │──── Ping Frame ─────────────────>│                   │
│   │                                 │                    │
│   │<─── Pong Frame ─────────────────│                    │
│   │                                 │                    │
│   │      (pingTimeout 내에 Pong 없으면 연결 종료)         │
└─────────────────────────────────────────────────────────┘
```

### 서버 측 하트비트 구현

```javascript
const WebSocket = require('ws');

const wss = new WebSocket.Server({ port: 8080 });

// 연결된 클라이언트 관리
const clients = new Map();

wss.on('connection', (ws) => {
  // 클라이언트 상태 초기화
  clients.set(ws, { isAlive: true });

  // Pong 응답 수신 시 상태 업데이트
  ws.on('pong', () => {
    const client = clients.get(ws);
    if (client) {
      client.isAlive = true;
    }
  });

  ws.on('close', () => {
    clients.delete(ws);
  });
});

// 주기적으로 Ping 전송
const HEARTBEAT_INTERVAL = 30000; // 30초

const heartbeatInterval = setInterval(() => {
  wss.clients.forEach((ws) => {
    const client = clients.get(ws);

    if (!client || !client.isAlive) {
      // 이전 Ping에 응답하지 않은 경우 연결 종료
      console.log('Client not responding, terminating');
      clients.delete(ws);
      return ws.terminate();
    }

    // 상태 초기화 후 Ping 전송
    client.isAlive = false;
    ws.ping();
  });
}, HEARTBEAT_INTERVAL);

wss.on('close', () => {
  clearInterval(heartbeatInterval);
});
```

### 클라이언트 측 하트비트 구현

```javascript
class WebSocketClient {
  constructor(url, options = {}) {
    this.url = url;
    this.options = {
      heartbeatInterval: 25000,  // 25초
      heartbeatTimeout: 10000,   // 10초
      reconnectInterval: 1000,   // 1초
      maxReconnectInterval: 30000, // 최대 30초
      reconnectDecay: 1.5,       // 지수 백오프 계수
      maxReconnectAttempts: 10,
      ...options
    };

    this.reconnectAttempts = 0;
    this.heartbeatTimer = null;
    this.heartbeatTimeoutTimer = null;

    this.connect();
  }

  connect() {
    this.ws = new WebSocket(this.url);

    this.ws.onopen = () => {
      console.log('Connected');
      this.reconnectAttempts = 0;
      this.startHeartbeat();
    };

    this.ws.onmessage = (event) => {
      // Pong 메시지 처리 (애플리케이션 레벨)
      if (event.data === 'pong') {
        this.resetHeartbeatTimeout();
        return;
      }
      this.onMessage(event.data);
    };

    this.ws.onclose = (event) => {
      console.log(`Disconnected: ${event.code}`);
      this.stopHeartbeat();
      this.reconnect();
    };

    this.ws.onerror = (error) => {
      console.error('WebSocket error:', error);
    };
  }

  startHeartbeat() {
    this.heartbeatTimer = setInterval(() => {
      if (this.ws.readyState === WebSocket.OPEN) {
        // 애플리케이션 레벨 Ping (텍스트 메시지)
        this.ws.send('ping');

        // 타임아웃 설정
        this.heartbeatTimeoutTimer = setTimeout(() => {
          console.log('Heartbeat timeout, closing connection');
          this.ws.close();
        }, this.options.heartbeatTimeout);
      }
    }, this.options.heartbeatInterval);
  }

  resetHeartbeatTimeout() {
    if (this.heartbeatTimeoutTimer) {
      clearTimeout(this.heartbeatTimeoutTimer);
      this.heartbeatTimeoutTimer = null;
    }
  }

  stopHeartbeat() {
    this.resetHeartbeatTimeout();
    if (this.heartbeatTimer) {
      clearInterval(this.heartbeatTimer);
      this.heartbeatTimer = null;
    }
  }

  reconnect() {
    if (this.reconnectAttempts >= this.options.maxReconnectAttempts) {
      console.log('Max reconnect attempts reached');
      return;
    }

    // 지수 백오프
    const delay = Math.min(
      this.options.reconnectInterval * Math.pow(
        this.options.reconnectDecay,
        this.reconnectAttempts
      ),
      this.options.maxReconnectInterval
    );

    console.log(`Reconnecting in ${delay}ms (attempt ${this.reconnectAttempts + 1})`);

    setTimeout(() => {
      this.reconnectAttempts++;
      this.connect();
    }, delay);
  }

  send(data) {
    if (this.ws.readyState === WebSocket.OPEN) {
      this.ws.send(data);
    }
  }

  onMessage(data) {
    // 오버라이드하여 사용
    console.log('Received:', data);
  }

  close() {
    this.stopHeartbeat();
    this.ws.close(1000, 'Normal closure');
  }
}

// 사용 예시
const client = new WebSocketClient('wss://example.com/socket', {
  heartbeatInterval: 30000,
  maxReconnectAttempts: 5
});
```

### 재연결 전략

```javascript
// 1. 즉시 재연결 (네트워크 일시 끊김)
// 2. 지수 백오프 (서버 과부하 방지)
// 3. 최대 시도 횟수 제한
// 4. Jitter 추가 (동시 재연결 방지)

function calculateReconnectDelay(attempt, options) {
  const { baseDelay, maxDelay, decayFactor } = options;

  // 지수 백오프
  let delay = baseDelay * Math.pow(decayFactor, attempt);

  // 최대 지연 제한
  delay = Math.min(delay, maxDelay);

  // Jitter 추가 (0.5 ~ 1.5 배)
  const jitter = 0.5 + Math.random();
  delay = Math.floor(delay * jitter);

  return delay;
}

// 예시: 1초, 2초, 4초, 8초, 16초... (최대 30초)
```

