```javascript
// 서버
const { Server } = require('socket.io');
const io = new Server(3000, {
  cors: {
    origin: 'http://localhost:3000',
    methods: ['GET', 'POST']
  },
  pingInterval: 25000,
  pingTimeout: 20000
});

