## 실전 구현 예제

### 채팅 서버 (Node.js + ws)

```javascript
// server.js
const WebSocket = require('ws');
const { v4: uuidv4 } = require('uuid');

const wss = new WebSocket.Server({ port: 8080 });

// 연결된 클라이언트와 룸 관리
const clients = new Map();
const rooms = new Map();

wss.on('connection', (ws) => {
  const clientId = uuidv4();
  clients.set(ws, { id: clientId, rooms: new Set() });

  console.log(`Client connected: ${clientId}`);

  // 연결 성공 알림
  send(ws, {
    type: 'connected',
    payload: { clientId }
  });

  ws.on('message', (message) => {
    try {
      const { type, payload } = JSON.parse(message);
      handleMessage(ws, type, payload);
    } catch (error) {
      send(ws, { type: 'error', payload: { message: 'Invalid message format' } });
    }
  });

  ws.on('close', () => {
    const client = clients.get(ws);
    if (client) {
      // 참여한 룸에서 퇴장 처리
      client.rooms.forEach((roomId) => {
        leaveRoom(ws, roomId);
      });
      clients.delete(ws);
      console.log(`Client disconnected: ${client.id}`);
    }
  });

  ws.on('pong', () => {
    const client = clients.get(ws);
    if (client) {
      client.isAlive = true;
    }
  });
});

function handleMessage(ws, type, payload) {
  const client = clients.get(ws);

  switch (type) {
    case 'join':
      joinRoom(ws, payload.roomId);
      break;

    case 'leave':
      leaveRoom(ws, payload.roomId);
      break;

    case 'message':
      broadcastToRoom(payload.roomId, {
        type: 'message',
        payload: {
          from: client.id,
          roomId: payload.roomId,
          text: payload.text,
          timestamp: Date.now()
        }
      }, ws);
      break;

    case 'typing':
      broadcastToRoom(payload.roomId, {
        type: 'typing',
        payload: { userId: client.id, roomId: payload.roomId }
      }, ws);
      break;
  }
}

function joinRoom(ws, roomId) {
  const client = clients.get(ws);

  if (!rooms.has(roomId)) {
    rooms.set(roomId, new Set());
  }

  rooms.get(roomId).add(ws);
  client.rooms.add(roomId);

  // 본인에게 확인
  send(ws, {
    type: 'joined',
    payload: { roomId, members: rooms.get(roomId).size }
  });

  // 다른 멤버들에게 알림
  broadcastToRoom(roomId, {
    type: 'user:joined',
    payload: { userId: client.id, roomId }
  }, ws);
}

function leaveRoom(ws, roomId) {
  const client = clients.get(ws);
  const room = rooms.get(roomId);

  if (room) {
    room.delete(ws);
    client.rooms.delete(roomId);

    broadcastToRoom(roomId, {
      type: 'user:left',
      payload: { userId: client.id, roomId }
    });

    // 빈 룸 정리
    if (room.size === 0) {
      rooms.delete(roomId);
    }
  }
}

function broadcastToRoom(roomId, message, excludeWs = null) {
  const room = rooms.get(roomId);
  if (!room) return;

  const messageStr = JSON.stringify(message);
  room.forEach((ws) => {
    if (ws !== excludeWs && ws.readyState === WebSocket.OPEN) {
      ws.send(messageStr);
    }
  });
}

function send(ws, message) {
  if (ws.readyState === WebSocket.OPEN) {
    ws.send(JSON.stringify(message));
  }
}

// 하트비트
const HEARTBEAT_INTERVAL = 30000;
const heartbeatInterval = setInterval(() => {
  wss.clients.forEach((ws) => {
    const client = clients.get(ws);
    if (!client || client.isAlive === false) {
      clients.delete(ws);
      return ws.terminate();
    }
    client.isAlive = false;
    ws.ping();
  });
}, HEARTBEAT_INTERVAL);

wss.on('close', () => {
  clearInterval(heartbeatInterval);
});

console.log('WebSocket server running on port 8080');
```

### 채팅 클라이언트 (React)

```jsx
// useWebSocket.js
import { useEffect, useRef, useState, useCallback } from 'react';

export function useWebSocket(url) {
  const [isConnected, setIsConnected] = useState(false);
  const [lastMessage, setLastMessage] = useState(null);
  const wsRef = useRef(null);
  const reconnectTimeoutRef = useRef(null);
  const reconnectAttempts = useRef(0);

  const connect = useCallback(() => {
    const ws = new WebSocket(url);

    ws.onopen = () => {
      console.log('Connected');
      setIsConnected(true);
      reconnectAttempts.current = 0;
    };

    ws.onmessage = (event) => {
      const message = JSON.parse(event.data);
      setLastMessage(message);
    };

    ws.onclose = () => {
      console.log('Disconnected');
      setIsConnected(false);

      // 재연결 (지수 백오프)
      const delay = Math.min(1000 * Math.pow(2, reconnectAttempts.current), 30000);
      reconnectTimeoutRef.current = setTimeout(() => {
        reconnectAttempts.current++;
        connect();
      }, delay);
    };

    ws.onerror = (error) => {
      console.error('WebSocket error:', error);
    };

    wsRef.current = ws;
  }, [url]);

  useEffect(() => {
    connect();

    return () => {
      if (reconnectTimeoutRef.current) {
        clearTimeout(reconnectTimeoutRef.current);
      }
      if (wsRef.current) {
        wsRef.current.close();
      }
    };
  }, [connect]);

  const sendMessage = useCallback((type, payload) => {
    if (wsRef.current?.readyState === WebSocket.OPEN) {
      wsRef.current.send(JSON.stringify({ type, payload }));
    }
  }, []);

  return { isConnected, lastMessage, sendMessage };
}

// ChatRoom.jsx
import React, { useState, useEffect } from 'react';
import { useWebSocket } from './useWebSocket';

function ChatRoom({ roomId }) {
  const [messages, setMessages] = useState([]);
  const [inputText, setInputText] = useState('');
  const { isConnected, lastMessage, sendMessage } = useWebSocket('ws://localhost:8080');

  // 룸 참여
  useEffect(() => {
    if (isConnected) {
      sendMessage('join', { roomId });
    }

    return () => {
      if (isConnected) {
        sendMessage('leave', { roomId });
      }
    };
  }, [isConnected, roomId, sendMessage]);

  // 메시지 수신 처리
  useEffect(() => {
    if (lastMessage) {
      switch (lastMessage.type) {
        case 'message':
          setMessages((prev) => [...prev, lastMessage.payload]);
          break;
        case 'user:joined':
          console.log('User joined:', lastMessage.payload.userId);
          break;
        case 'user:left':
          console.log('User left:', lastMessage.payload.userId);
          break;
      }
    }
  }, [lastMessage]);

  const handleSend = () => {
    if (inputText.trim()) {
      sendMessage('message', { roomId, text: inputText });
      setInputText('');
    }
  };

  return (
    <div className="chat-room">
      <div className="status">
        {isConnected ? 'Connected' : 'Disconnected'}
      </div>

      <div className="messages">
        {messages.map((msg, index) => (
          <div key={index} className="message">
            <span className="from">{msg.from}:</span>
            <span className="text">{msg.text}</span>
          </div>
        ))}
      </div>

      <div className="input">
        <input
          type="text"
          value={inputText}
          onChange={(e) => setInputText(e.target.value)}
          onKeyPress={(e) => e.key === 'Enter' && handleSend()}
          disabled={!isConnected}
        />
        <button onClick={handleSend} disabled={!isConnected}>
          Send
        </button>
      </div>
    </div>
  );
}

export default ChatRoom;
```

