// 해결: flush 호출
@Test
@Transactional
void shouldFailForDuplicateEmail() {
    userService.createUser("John", "john@example.com");
    entityManager.flush();  // 즉시 DB에 반영

    assertThrows(DataIntegrityViolationException.class, () -> {
        userService.createUser("Jane", "john@example.com");
        entityManager.flush();
    });
}
