## 2. Declarative vs Scripted Pipeline

### 2.1 비교 개요

```
┌─────────────────────────────────────────────────────────────────────────┐
│                Declarative vs Scripted Pipeline 비교                     │
├────────────────────────────────┬────────────────────────────────────────┤
│      Declarative Pipeline      │        Scripted Pipeline               │
├────────────────────────────────┼────────────────────────────────────────┤
│ • pipeline { } 으로 시작        │ • node { } 으로 시작                    │
│ • 정형화된 구조                 │ • 자유로운 Groovy 스크립트              │
│ • 문법 검증 용이                │ • 복잡한 로직 표현 가능                 │
│ • 초보자 친화적                 │ • Groovy 지식 필요                     │
│ • 가독성 높음                   │ • 유연성 높음                          │
│ • 제한된 Groovy 사용            │ • 전체 Groovy 기능 사용                │
│ • Blue Ocean UI 지원           │ • 레거시 파이프라인                     │
│ • 현재 권장 방식                │ • 복잡한 요구사항에 사용               │
└────────────────────────────────┴────────────────────────────────────────┘
```

### 2.2 Declarative Pipeline 문법

```groovy
// Jenkinsfile (Declarative)
pipeline {
    // 실행 환경 정의
    agent {
        kubernetes {
            yaml '''
apiVersion: v1
kind: Pod
spec:
  containers:
  - name: maven
    image: maven:3.9.6-eclipse-temurin-21
    command:
    - sleep
    args:
    - infinity
  - name: docker
    image: docker:24-dind
    securityContext:
      privileged: true
'''
        }
    }

    // 환경 변수
    environment {
        DOCKER_REGISTRY = 'ghcr.io'
        IMAGE_NAME = 'myorg/myapp'
        MAVEN_OPTS = '-Dmaven.repo.local=.m2/repository'
    }

    // 옵션 설정
    options {
        timeout(time: 30, unit: 'MINUTES')
        disableConcurrentBuilds()
        buildDiscarder(logRotator(numToKeepStr: '10'))
        timestamps()
    }

    // 파라미터 정의
    parameters {
        string(name: 'BRANCH', defaultValue: 'main', description: 'Branch to build')
        choice(name: 'ENVIRONMENT', choices: ['dev', 'staging', 'prod'], description: 'Target environment')
        booleanParam(name: 'SKIP_TESTS', defaultValue: false, description: 'Skip tests')
    }

    // 트리거 설정
    triggers {
        pollSCM('H/5 * * * *')  // 5분마다 SCM 폴링
        cron('H 2 * * *')       // 매일 새벽 2시 빌드
    }

    // 파이프라인 단계
    stages {
        stage('Checkout') {
            steps {
                checkout scm
                script {
                    env.GIT_COMMIT_SHORT = sh(
                        script: 'git rev-parse --short HEAD',
                        returnStdout: true
                    ).trim()
                }
            }
        }

        stage('Build') {
            steps {
                container('maven') {
                    sh 'mvn clean package -DskipTests'
                }
            }
        }

        stage('Test') {
            when {
                expression { params.SKIP_TESTS == false }
            }
            parallel {
                stage('Unit Tests') {
                    steps {
                        container('maven') {
                            sh 'mvn test'
                        }
                    }
                    post {
                        always {
                            junit '**/target/surefire-reports/*.xml'
                        }
                    }
                }
                stage('Integration Tests') {
                    steps {
                        container('maven') {
                            sh 'mvn verify -DskipUnitTests'
                        }
                    }
                }
            }
        }

        stage('Code Quality') {
            steps {
                container('maven') {
                    withSonarQubeEnv('SonarQube') {
                        sh 'mvn sonar:sonar'
                    }
                }
            }
        }

        stage('Quality Gate') {
            steps {
                timeout(time: 10, unit: 'MINUTES') {
                    waitForQualityGate abortPipeline: true
                }
            }
        }

        stage('Build Image') {
            steps {
                container('docker') {
                    sh """
                        docker build -t ${DOCKER_REGISTRY}/${IMAGE_NAME}:${GIT_COMMIT_SHORT} .
                        docker tag ${DOCKER_REGISTRY}/${IMAGE_NAME}:${GIT_COMMIT_SHORT} \
                                   ${DOCKER_REGISTRY}/${IMAGE_NAME}:latest
                    """
                }
            }
        }

        stage('Push Image') {
            steps {
                container('docker') {
                    withCredentials([usernamePassword(
                        credentialsId: 'docker-registry',
                        usernameVariable: 'DOCKER_USER',
                        passwordVariable: 'DOCKER_PASS'
                    )]) {
                        sh """
                            echo \$DOCKER_PASS | docker login ${DOCKER_REGISTRY} -u \$DOCKER_USER --password-stdin
                            docker push ${DOCKER_REGISTRY}/${IMAGE_NAME}:${GIT_COMMIT_SHORT}
                            docker push ${DOCKER_REGISTRY}/${IMAGE_NAME}:latest
                        """
                    }
                }
            }
        }

        stage('Deploy') {
            when {
                branch 'main'
            }
            steps {
                input message: 'Deploy to production?', ok: 'Deploy'
                echo "Deploying to ${params.ENVIRONMENT}"
            }
        }
    }

    // 후처리
    post {
        always {
            cleanWs()
        }
        success {
            slackSend(
                color: 'good',
                message: "Build Succeeded: ${env.JOB_NAME} #${env.BUILD_NUMBER}"
            )
        }
        failure {
            slackSend(
                color: 'danger',
                message: "Build Failed: ${env.JOB_NAME} #${env.BUILD_NUMBER}"
            )
        }
    }
}
```

### 2.3 Scripted Pipeline 문법

```groovy
// Jenkinsfile (Scripted)
node('kubernetes') {
    def dockerImage
    def gitCommit

    try {
        stage('Checkout') {
            checkout scm
            gitCommit = sh(script: 'git rev-parse --short HEAD', returnStdout: true).trim()
        }

        stage('Build') {
            // 조건부 로직
            if (env.BRANCH_NAME == 'main') {
                sh 'mvn clean package -Pprod'
            } else {
                sh 'mvn clean package -Pdev'
            }
        }

        stage('Test') {
            // 병렬 실행
            parallel(
                'Unit Tests': {
                    sh 'mvn test'
                },
                'Integration Tests': {
                    sh 'mvn verify -DskipUnitTests'
                }
            )
        }

        // 동적 스테이지 생성
        def environments = ['dev', 'staging', 'prod']
        environments.each { env ->
            stage("Deploy to ${env}") {
                if (shouldDeploy(env, env.BRANCH_NAME)) {
                    deployTo(env, gitCommit)
                } else {
                    echo "Skipping ${env} deployment"
                }
            }
        }

        currentBuild.result = 'SUCCESS'
    } catch (Exception e) {
        currentBuild.result = 'FAILURE'
        throw e
    } finally {
        // 정리 작업
        cleanWs()
        notifyBuildResult()
    }
}

// 헬퍼 함수
def shouldDeploy(environment, branch) {
    switch(environment) {
        case 'dev':
            return true
        case 'staging':
            return branch == 'develop'
        case 'prod':
            return branch == 'main'
        default:
            return false
    }
}

def deployTo(environment, version) {
    echo "Deploying version ${version} to ${environment}"
    // 배포 로직
}

def notifyBuildResult() {
    def color = currentBuild.result == 'SUCCESS' ? 'good' : 'danger'
    slackSend(color: color, message: "${env.JOB_NAME} - ${currentBuild.result}")
}
```

### 2.4 언제 어떤 것을 사용해야 하나?

```
┌─────────────────────────────────────────────────────────────────────────┐
│                        Pipeline 선택 가이드                              │
├─────────────────────────────────────────────────────────────────────────┤
│                                                                          │
│  Declarative Pipeline 선택:                                              │
│  ✓ 신규 프로젝트                                                         │
│  ✓ 표준적인 CI/CD 워크플로우                                              │
│  ✓ 팀에 Jenkins 전문가가 없는 경우                                        │
