## 5. ArgoCD 설정 및 사용법

### 5.1 ArgoCD 설치

```bash
# Namespace 생성 및 ArgoCD 설치
kubectl create namespace argocd
kubectl apply -n argocd -f https://raw.githubusercontent.com/argoproj/argo-cd/stable/manifests/install.yaml

# 초기 admin 비밀번호 확인
kubectl -n argocd get secret argocd-initial-admin-secret \
    -o jsonpath="{.data.password}" | base64 -d

# CLI 로그인
argocd login localhost:8080 --username admin --password <password>

# 비밀번호 변경
argocd account update-password
```

### 5.2 Application 정의 (선언적)

```yaml
# application.yaml
apiVersion: argoproj.io/v1alpha1
kind: Application
metadata:
  name: my-app
  namespace: argocd
  # 삭제 시 리소스도 함께 삭제
  finalizers:
    - resources-finalizer.argocd.argoproj.io
spec:
  project: default

  # 소스 정의 (Git 저장소)
  source:
    repoURL: https://github.com/myorg/my-app-manifests.git
    targetRevision: main
    path: overlays/production

    # Kustomize 옵션
    kustomize:
      namePrefix: prod-
      images:
        - myregistry/myapp:v1.2.3

    # 또는 Helm 옵션
    # helm:
    #   releaseName: my-app
    #   valueFiles:
    #     - values-prod.yaml
    #   values: |
    #     replicaCount: 3
    #     image:
    #       tag: v1.2.3

  # 대상 클러스터
  destination:
    server: https://kubernetes.default.svc
    namespace: production

  # 동기화 정책
  syncPolicy:
    automated:
      prune: true       # Git에서 삭제된 리소스도 삭제
      selfHeal: true    # 수동 변경 시 자동 복구
      allowEmpty: false # 빈 디렉토리 허용 안함

    syncOptions:
      - CreateNamespace=true
      - PrunePropagationPolicy=foreground
      - PruneLast=true

    # 재시도 정책
    retry:
      limit: 5
      backoff:
        duration: 5s
        factor: 2
        maxDuration: 3m

  # 무시할 차이
  ignoreDifferences:
    - group: apps
      kind: Deployment
      jsonPointers:
        - /spec/replicas  # HPA가 관리하는 경우
```

### 5.3 AppProject 설정

```yaml
# app-project.yaml
apiVersion: argoproj.io/v1alpha1
kind: AppProject
metadata:
  name: production
  namespace: argocd
spec:
  description: Production applications

  # 소스 저장소 제한
  sourceRepos:
    - 'https://github.com/myorg/*'
    - 'https://charts.helm.sh/stable'

  # 대상 클러스터/네임스페이스 제한
  destinations:
    - namespace: 'production'
      server: https://kubernetes.default.svc
    - namespace: 'production-*'
      server: https://kubernetes.default.svc

  # 배포 가능한 리소스 제한
  clusterResourceWhitelist:
    - group: ''
      kind: Namespace
    - group: rbac.authorization.k8s.io
      kind: ClusterRole
    - group: rbac.authorization.k8s.io
      kind: ClusterRoleBinding

  namespaceResourceBlacklist:
    - group: ''
      kind: Secret  # Secret 직접 배포 금지

  # 역할 정의 (RBAC)
  roles:
    - name: developer
      description: Developer role
      policies:
        - p, proj:production:developer, applications, get, production/*, allow
        - p, proj:production:developer, applications, sync, production/*, allow
      groups:
        - my-org:developers

    - name: admin
      description: Admin role
      policies:
        - p, proj:production:admin, applications, *, production/*, allow
      groups:
        - my-org:admins

  # Sync Window (배포 시간 제한)
  syncWindows:
    - kind: allow
      schedule: '0 9-18 * * 1-5'  # 평일 09:00-18:00
      duration: 9h
      applications:
        - '*'
    - kind: deny
      schedule: '0 0 * * 0'       # 일요일 전체
      duration: 24h
      applications:
        - '*-critical'
```

### 5.4 Kustomize와 함께 사용

```
# 디렉토리 구조
my-app-manifests/
├── base/
│   ├── kustomization.yaml
│   ├── deployment.yaml
│   ├── service.yaml
│   └── configmap.yaml
└── overlays/
    ├── development/
    │   ├── kustomization.yaml
    │   └── replica-patch.yaml
    ├── staging/
    │   ├── kustomization.yaml
    │   └── replica-patch.yaml
    └── production/
        ├── kustomization.yaml
        ├── replica-patch.yaml
        └── resource-patch.yaml
```

```yaml
# base/kustomization.yaml
apiVersion: kustomize.config.k8s.io/v1beta1
kind: Kustomization

resources:
  - deployment.yaml
  - service.yaml
  - configmap.yaml

commonLabels:
  app: my-app

---
# overlays/production/kustomization.yaml
apiVersion: kustomize.config.k8s.io/v1beta1
kind: Kustomization

namespace: production

resources:
  - ../../base

namePrefix: prod-

images:
  - name: myregistry/myapp
    newTag: v1.2.3

replicas:
  - name: my-app
    count: 5

patches:
  - path: resource-patch.yaml

---
# overlays/production/resource-patch.yaml
apiVersion: apps/v1
kind: Deployment
metadata:
  name: my-app
spec:
  template:
    spec:
      containers:
        - name: my-app
          resources:
            requests:
              memory: "512Mi"
              cpu: "500m"
            limits:
              memory: "1Gi"
              cpu: "1000m"
```

