## 성능 튜닝

### worker_processes

Worker 프로세스 수를 설정합니다. 일반적으로 **CPU 코어 수**와 동일하게 설정합니다.

```nginx
# 자동 감지 (권장)
worker_processes auto;

# 수동 설정
worker_processes 4;

# CPU 코어별 Worker 할당 (CPU affinity)
worker_processes 4;
worker_cpu_affinity 0001 0010 0100 1000;  # 각 Worker를 특정 코어에 바인딩

# 자동 CPU affinity (권장)
worker_cpu_affinity auto;
```

#### 컨테이너 환경 주의사항

```nginx
# Docker/Kubernetes 환경에서는 auto가 호스트 코어 수를 감지할 수 있음
# 컨테이너에 할당된 CPU 수에 맞게 명시적으로 설정

# 예: 2 CPU 제한된 컨테이너
worker_processes 2;
```

### worker_connections

각 Worker가 처리할 수 있는 **최대 동시 연결 수**입니다.

```nginx
events {
    # 기본값: 512, 일반적으로 1024~4096 권장
    worker_connections 4096;

    # 새 연결을 한 번에 여러 개 수락
    multi_accept on;

    # 이벤트 처리 방식 지정 (Linux)
    use epoll;
}
```

#### 최대 연결 수 계산

```
최대 클라이언트 수 = worker_processes × worker_connections

예: 4 Workers × 4096 connections = 16,384 동시 연결

※ 실제로는 시스템의 파일 디스크립터 제한(~65,535)에 의해 제한됨
※ 리버스 프록시 사용 시, 클라이언트 연결 + 백엔드 연결로 2배 필요
```

### 파일 디스크립터 제한

```nginx
# nginx.conf
worker_rlimit_nofile 100000;  # Worker당 열 수 있는 최대 파일 수
```

```bash
# 시스템 레벨 설정 (/etc/security/limits.conf)
nginx soft nofile 100000
nginx hard nofile 100000

# 또는 systemd 서비스 파일
[Service]
LimitNOFILE=100000
```

### 버퍼 최적화

```nginx
http {
    # 클라이언트 요청 버퍼
    client_body_buffer_size 16k;
    client_header_buffer_size 1k;
    client_max_body_size 100m;
    large_client_header_buffers 4 8k;

    # 프록시 버퍼
    proxy_buffer_size 4k;
    proxy_buffers 8 16k;
    proxy_busy_buffers_size 24k;

    # 타임아웃 설정
    client_body_timeout 12;
    client_header_timeout 12;
    send_timeout 10;
    keepalive_timeout 65;
    keepalive_requests 1000;
}
```

### 종합 성능 최적화 설정

```nginx
user nginx;
worker_processes auto;
worker_cpu_affinity auto;
worker_rlimit_nofile 100000;
error_log /var/log/nginx/error.log warn;
pid /var/run/nginx.pid;

events {
    worker_connections 4096;
    multi_accept on;
    use epoll;
}

http {
    include /etc/nginx/mime.types;
    default_type application/octet-stream;

    # 로그 포맷
    log_format main '$remote_addr - $remote_user [$time_local] "$request" '
                    '$status $body_bytes_sent "$http_referer" '
                    '"$http_user_agent" "$http_x_forwarded_for" '
                    'rt=$request_time uct="$upstream_connect_time" '
                    'uht="$upstream_header_time" urt="$upstream_response_time"';

    access_log /var/log/nginx/access.log main buffer=16k flush=2m;

    # 성능 최적화
    sendfile on;
    tcp_nopush on;
    tcp_nodelay on;

    # Keepalive
    keepalive_timeout 65;
    keepalive_requests 1000;

    # 해시 테이블 크기
    types_hash_max_size 2048;
    server_names_hash_bucket_size 64;

    # 버전 정보 숨기기
    server_tokens off;

    include /etc/nginx/conf.d/*.conf;
}
```

