## Rate Limiting

Nginx의 Rate Limiting은 **Leaky Bucket 알고리즘**을 사용하여 요청 속도를 제한합니다.

### 요청 수 제한 (limit_req)

```nginx
http {
    # 제한 영역 정의
    # $binary_remote_addr: 클라이언트 IP (4바이트 IPv4, 16바이트 IPv6)
    # zone=mylimit:10m: 10MB 공유 메모리 (약 160,000 IP 저장 가능)
    # rate=10r/s: 초당 10개 요청
    limit_req_zone $binary_remote_addr zone=mylimit:10m rate=10r/s;

    # 분당 요청 제한
    limit_req_zone $binary_remote_addr zone=permin:10m rate=60r/m;

    server {
        # 기본 적용 (초과 요청 즉시 거부)
        location /api/ {
            limit_req zone=mylimit;
            proxy_pass http://backend;
        }

        # burst 허용 (초과 요청을 큐에 대기)
        location /api/search {
            limit_req zone=mylimit burst=20;
            proxy_pass http://backend;
        }

        # burst + nodelay (버스트 요청 즉시 처리)
        location /api/submit {
            limit_req zone=mylimit burst=20 nodelay;
            proxy_pass http://backend;
        }
    }
}
```

#### burst와 nodelay 이해

```
rate=10r/s, burst=20 설정 시:

[burst 없음]
- 100ms마다 1개 요청 허용
- 초과 요청 즉시 503 반환

[burst=20]
- 초과 요청을 20개까지 큐에 대기
- 큐의 요청은 100ms 간격으로 처리
- 20개 초과 시 503 반환

[burst=20 nodelay]
- 처음 21개 요청(1 + burst) 즉시 처리
- 이후 100ms마다 버스트 슬롯 1개 회복
- 슬롯 소진 후 초과 요청은 503 반환
```

### 연결 수 제한 (limit_conn)

```nginx
http {
    # IP당 연결 수 제한
    limit_conn_zone $binary_remote_addr zone=addr:10m;

    # 서버당 연결 수 제한
    limit_conn_zone $server_name zone=servers:10m;

    server {
        # IP당 최대 10개 연결
        limit_conn addr 10;

        # 다운로드 영역: IP당 1개 연결, 속도 제한
        location /download/ {
            limit_conn addr 1;
            limit_rate 100k;  # 100KB/s 속도 제한
        }
    }
}
```

### 로그인/API 보호 예제

```nginx
http {
    # 로그인 시도 제한 (분당 5회)
    limit_req_zone $binary_remote_addr zone=login:10m rate=5r/m;

    # API 전체 제한 (초당 100회)
    limit_req_zone $binary_remote_addr zone=api:10m rate=100r/s;

    # 커스텀 에러 코드
    limit_req_status 429;
    limit_conn_status 429;

    server {
        # 로그인 엔드포인트 보호
        location /api/login {
            limit_req zone=login burst=3 nodelay;

            # 429 에러 페이지
            error_page 429 = @rate_limited;

            proxy_pass http://backend;
        }

        location @rate_limited {
            default_type application/json;
            return 429 '{"error": "Too Many Requests", "retry_after": 60}';
        }

        # 일반 API
        location /api/ {
            limit_req zone=api burst=50 nodelay;
            proxy_pass http://backend;
        }
    }
}
```

### 화이트리스트 설정

```nginx
http {
    # geo 모듈로 IP 매핑
    geo $limit {
        default 1;
        10.0.0.0/8 0;      # 내부 네트워크 제외
        192.168.0.0/16 0;  # 내부 네트워크 제외
    }

    # 제한 대상만 키로 사용
    map $limit $limit_key {
        0 "";
        1 $binary_remote_addr;
    }

    limit_req_zone $limit_key zone=api:10m rate=10r/s;

    server {
        location /api/ {
            limit_req zone=api burst=20;
            proxy_pass http://backend;
        }
    }
}
```

