        // 예: 락 경합 발생 코드
        private final Object lock = new Object();

        public void contentionExample() {
            synchronized (lock) {
                // 긴 작업 -> 다른 스레드 대기
                heavyOperation();
            }
        }

        // 해결: 락 범위 최소화
        public void reducedContention() {
            Data data;
            synchronized (lock) {
                data = fetchData();  // 빠른 작업만 락 안에서
            }
            processData(data);  // 락 밖에서 처리
        }
    }
}
