/**
 * QueryDSL을 활용한 최적화된 조회
 */
@Repository
@RequiredArgsConstructor
public class OrderQueryRepository {

    private final JPAQueryFactory queryFactory;

    /**
     * 페이징 + 필터링 최적화
     * - 커버링 인덱스 활용
     * - 서브쿼리로 ID만 먼저 조회
     */
    public Page<OrderDto> findOrdersOptimized(OrderSearchCondition condition, Pageable pageable) {
        // 1. 커버링 인덱스로 ID만 조회
        List<Long> ids = queryFactory
            .select(order.id)
            .from(order)
            .where(
                statusEq(condition.getStatus()),
                createdAtBetween(condition.getStartDate(), condition.getEndDate())
            )
            .orderBy(order.id.desc())
            .offset(pageable.getOffset())
            .limit(pageable.getPageSize())
            .fetch();

        if (ids.isEmpty()) {
            return Page.empty(pageable);
        }

        // 2. ID로 실제 데이터 조회 (IN 쿼리)
        List<OrderDto> content = queryFactory
            .select(new QOrderDto(
                order.id,
                order.status,
                order.totalAmount,
                order.createdAt
            ))
            .from(order)
            .where(order.id.in(ids))
            .orderBy(order.id.desc())
            .fetch();

        // 3. 전체 카운트 (별도 최적화)
        Long total = queryFactory
            .select(order.count())
            .from(order)
            .where(
                statusEq(condition.getStatus()),
                createdAtBetween(condition.getStartDate(), condition.getEndDate())
            )
            .fetchOne();

        return new PageImpl<>(content, pageable, total);
    }
}
