### 서킷 브레이커 기본 구현

```java
/**
 * 서킷 브레이커 직접 구현 (개념 이해용)
 */
public class SimpleCircuitBreaker {

    private enum State {
        CLOSED, OPEN, HALF_OPEN
    }

    private State state = State.CLOSED;
    private int failureCount = 0;
    private int successCount = 0;
    private long lastFailureTime = 0;

    private final int failureThreshold;
    private final long resetTimeoutMs;
    private final int halfOpenMaxCalls;

    public SimpleCircuitBreaker(int failureThreshold, long resetTimeoutMs, int halfOpenMaxCalls) {
        this.failureThreshold = failureThreshold;
        this.resetTimeoutMs = resetTimeoutMs;
        this.halfOpenMaxCalls = halfOpenMaxCalls;
    }

    public <T> T execute(Supplier<T> action, Supplier<T> fallback) {
        if (!allowRequest()) {
            return fallback.get();
        }

        try {
            T result = action.get();
            onSuccess();
            return result;
        } catch (Exception e) {
            onFailure();
            return fallback.get();
        }
    }

    private synchronized boolean allowRequest() {
        switch (state) {
            case CLOSED:
                return true;

            case OPEN:
                if (System.currentTimeMillis() - lastFailureTime >= resetTimeoutMs) {
                    state = State.HALF_OPEN;
                    failureCount = 0;
                    successCount = 0;
                    return true;
                }
                return false;

            case HALF_OPEN:
                return successCount + failureCount < halfOpenMaxCalls;

            default:
                return false;
        }
    }

    private synchronized void onSuccess() {
        switch (state) {
            case HALF_OPEN:
                successCount++;
                if (successCount >= halfOpenMaxCalls) {
                    state = State.CLOSED;
                    failureCount = 0;
                }
                break;

            case CLOSED:
                failureCount = 0;  // 성공 시 실패 카운트 리셋
                break;
        }
    }

    private synchronized void onFailure() {
        lastFailureTime = System.currentTimeMillis();

        switch (state) {
            case CLOSED:
                failureCount++;
                if (failureCount >= failureThreshold) {
                    state = State.OPEN;
                }
                break;

            case HALF_OPEN:
                state = State.OPEN;
                break;
        }
    }
}
