    path: req.path,
    userAgent: req.headers['user-agent'],
    ip: req.ip,
  });

  req.log.info('request_received');

  res.on('finish', () => {
    req.log.info({
      statusCode: res.statusCode,
      responseTimeMs: Date.now() - startTime,
    }, 'request_completed');
  });

  next();
};

