### select()

```c
#include <sys/select.h>

int select(int nfds, fd_set *readfds, fd_set *writefds,
           fd_set *exceptfds, struct timeval *timeout);

// nfds: 감시할 fd 중 가장 큰 값 + 1
// readfds: 읽기 가능 여부 감시할 fd 집합
// writefds: 쓰기 가능 여부 감시할 fd 집합
// exceptfds: 예외 상황 감시할 fd 집합
// timeout: 타임아웃 (NULL이면 무한 대기)

// fd_set 매크로:
// FD_ZERO(&set)     - 집합 초기화
// FD_SET(fd, &set)  - fd 추가
// FD_CLR(fd, &set)  - fd 제거
// FD_ISSET(fd, &set) - fd 포함 여부 확인
```

```c
// select() 사용 예제
#include <sys/select.h>

int main() {
    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    // ... bind, listen ...

    fd_set master_set, read_set;
    FD_ZERO(&master_set);
    FD_SET(server_fd, &master_set);
    int max_fd = server_fd;

    while (1) {
        read_set = master_set;  // select()가 수정하므로 복사

        struct timeval timeout = {.tv_sec = 5, .tv_usec = 0};
        int ready = select(max_fd + 1, &read_set, NULL, NULL, &timeout);

        if (ready < 0) {
            perror("select error");
            break;
        }

        if (ready == 0) {
            printf("Timeout\n");
            continue;
        }

        for (int fd = 0; fd <= max_fd; fd++) {
            if (!FD_ISSET(fd, &read_set)) continue;

            if (fd == server_fd) {
                // 새 연결 수락
                int client_fd = accept(server_fd, NULL, NULL);
                FD_SET(client_fd, &master_set);
                if (client_fd > max_fd) max_fd = client_fd;
                printf("New connection: fd=%d\n", client_fd);
            }
            else {
                // 클라이언트 데이터 처리
                char buffer[1024];
                ssize_t bytes = recv(fd, buffer, sizeof(buffer), 0);

                if (bytes <= 0) {
                    close(fd);
                    FD_CLR(fd, &master_set);
                    printf("Connection closed: fd=%d\n", fd);
                }
                else {
                    buffer[bytes] = '\0';
                    send(fd, buffer, bytes, 0);  // Echo
                }
            }
        }
    }

    return 0;
}
```

**select()의 한계**:
- fd 수 제한 (FD_SETSIZE, 보통 1024)
- 매번 fd_set 복사 필요
- O(n) 순회 필요

### poll()

```c
#include <poll.h>

int poll(struct pollfd *fds, nfds_t nfds, int timeout);

struct pollfd {
    int   fd;         // 파일 디스크립터
    short events;     // 감시할 이벤트
    short revents;    // 발생한 이벤트 (출력)
};

// 주요 이벤트:
// POLLIN   - 읽기 가능
// POLLOUT  - 쓰기 가능
// POLLERR  - 오류 발생
// POLLHUP  - 연결 종료
// POLLNVAL - 잘못된 fd
```

```c
// poll() 사용 예제
#include <poll.h>

#define MAX_CLIENTS 1000

int main() {
    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    // ... bind, listen ...

    struct pollfd fds[MAX_CLIENTS];
    int nfds = 1;

    fds[0].fd = server_fd;
    fds[0].events = POLLIN;

    while (1) {
        int ready = poll(fds, nfds, 5000);  // 5초 타임아웃

        if (ready < 0) {
            perror("poll error");
            break;
        }

        for (int i = 0; i < nfds; i++) {
            if (fds[i].revents == 0) continue;

            if (fds[i].fd == server_fd) {
                // 새 연결
                int client_fd = accept(server_fd, NULL, NULL);
                fds[nfds].fd = client_fd;
                fds[nfds].events = POLLIN;
                nfds++;
            }
            else {
                // 클라이언트 데이터
                char buffer[1024];
                ssize_t bytes = recv(fds[i].fd, buffer, sizeof(buffer), 0);

                if (bytes <= 0) {
                    close(fds[i].fd);
                    // 배열에서 제거
                    fds[i] = fds[nfds - 1];
                    nfds--;
                    i--;
                }
                else {
                    send(fds[i].fd, buffer, bytes, 0);
                }
            }
        }
    }

    return 0;
}
```

### epoll (Linux)

```c
#include <sys/epoll.h>

// epoll 인스턴스 생성
int epoll_create(int size);      // size는 힌트 (무시됨)
int epoll_create1(int flags);    // flags: EPOLL_CLOEXEC

// fd 추가/수정/삭제
int epoll_ctl(int epfd, int op, int fd, struct epoll_event *event);
// op: EPOLL_CTL_ADD, EPOLL_CTL_MOD, EPOLL_CTL_DEL

// 이벤트 대기
int epoll_wait(int epfd, struct epoll_event *events,
               int maxevents, int timeout);

struct epoll_event {
    uint32_t events;    // 이벤트 마스크
    epoll_data_t data;  // 사용자 데이터
};

// 주요 이벤트:
// EPOLLIN      - 읽기 가능
// EPOLLOUT     - 쓰기 가능
// EPOLLERR     - 오류
// EPOLLHUP     - 연결 종료
// EPOLLET      - Edge Triggered 모드
// EPOLLONESHOT - 한 번만 알림
```

```c
// epoll 사용 예제
#include <sys/epoll.h>
#include <fcntl.h>

#define MAX_EVENTS 1024

void set_nonblocking(int fd) {
    int flags = fcntl(fd, F_GETFL, 0);
    fcntl(fd, F_SETFL, flags | O_NONBLOCK);
}

int main() {
    int server_fd = socket(AF_INET, SOCK_STREAM | SOCK_NONBLOCK, 0);
    // ... bind, listen ...

    // epoll 인스턴스 생성
    int epfd = epoll_create1(0);

    // 서버 소켓 등록
    struct epoll_event ev;
    ev.events = EPOLLIN;
    ev.data.fd = server_fd;
    epoll_ctl(epfd, EPOLL_CTL_ADD, server_fd, &ev);

    struct epoll_event events[MAX_EVENTS];

    while (1) {
        int nready = epoll_wait(epfd, events, MAX_EVENTS, -1);

        for (int i = 0; i < nready; i++) {
            int fd = events[i].data.fd;

            if (fd == server_fd) {
                // 새 연결
                while (1) {
                    int client_fd = accept(server_fd, NULL, NULL);
                    if (client_fd < 0) {
                        if (errno == EAGAIN) break;  // 모든 연결 처리 완료
                        perror("accept");
                        break;
                    }

                    set_nonblocking(client_fd);

                    ev.events = EPOLLIN | EPOLLET;  // Edge Triggered
                    ev.data.fd = client_fd;
                    epoll_ctl(epfd, EPOLL_CTL_ADD, client_fd, &ev);

                    printf("New connection: fd=%d\n", client_fd);
                }
            }
            else {
                // 클라이언트 데이터
                if (events[i].events & (EPOLLERR | EPOLLHUP)) {
                    close(fd);
                    continue;
                }

                char buffer[1024];
                while (1) {
                    ssize_t bytes = recv(fd, buffer, sizeof(buffer), 0);

                    if (bytes < 0) {
                        if (errno == EAGAIN) break;  // 모든 데이터 읽음
                        close(fd);
                        break;
                    }

                    if (bytes == 0) {
                        close(fd);
                        break;
                    }

                    send(fd, buffer, bytes, 0);
                }
            }
        }
    }

    close(epfd);
    close(server_fd);
    return 0;
}
```

### Level Triggered vs Edge Triggered

```
Level Triggered (LT, 기본):
- 조건이 만족되는 동안 계속 이벤트 발생
- 버퍼에 데이터가 있으면 계속 EPOLLIN 반환
- select/poll과 동일한 동작

Edge Triggered (ET):
- 상태가 변경될 때만 이벤트 발생
- 새 데이터가 도착했을 때만 EPOLLIN 반환
- 한 번에 모든 데이터를 읽어야 함 (EAGAIN까지)
- 더 효율적이지만 주의 필요

┌─────────────────────────────────────────────────────────────┐
│  버퍼 상태:  [████████░░░░] (8KB 데이터)                     │
│                                                             │
│  Level Triggered:                                           │
│    epoll_wait() → EPOLLIN                                   │
│    read(4KB)    → 버퍼에 4KB 남음                            │
│    epoll_wait() → EPOLLIN (아직 데이터 있음)                 │
│    read(4KB)    → 버퍼 비움                                  │
│    epoll_wait() → (대기)                                     │
│                                                             │
│  Edge Triggered:                                            │
│    epoll_wait() → EPOLLIN                                   │
│    read(4KB)    → 버퍼에 4KB 남음                            │
│    epoll_wait() → (대기! 새 데이터 올 때까지)                 │
│                   ⚠️ 남은 4KB는 영원히 읽히지 않음!           │
│                                                             │
│  Edge Triggered 올바른 사용:                                 │
│    epoll_wait() → EPOLLIN                                   │
│    while (1) {                                              │
│      read() → EAGAIN까지 반복                                │
│    }                                                        │
└─────────────────────────────────────────────────────────────┘
```

### kqueue (BSD/macOS)

```c
#include <sys/event.h>

// kqueue 인스턴스 생성
int kqueue(void);

// 이벤트 등록/대기
int kevent(int kq,
           const struct kevent *changelist, int nchanges,
           struct kevent *eventlist, int nevents,
           const struct timespec *timeout);

struct kevent {
    uintptr_t  ident;   // 식별자 (fd)
    int16_t    filter;  // 필터 타입
    uint16_t   flags;   // 동작 플래그
    uint32_t   fflags;  // 필터별 플래그
    intptr_t   data;    // 필터별 데이터
    void       *udata;  // 사용자 데이터
};

// 주요 필터:
// EVFILT_READ   - 읽기 가능
// EVFILT_WRITE  - 쓰기 가능
// EVFILT_TIMER  - 타이머

// 주요 플래그:
// EV_ADD        - 이벤트 추가
// EV_DELETE     - 이벤트 삭제
// EV_ENABLE     - 이벤트 활성화
// EV_DISABLE    - 이벤트 비활성화
// EV_CLEAR      - 이벤트 자동 클리어 (Edge Triggered 유사)
```

```c
// kqueue 사용 예제 (macOS/BSD)
#include <sys/event.h>

#define MAX_EVENTS 1024

int main() {
    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    // ... bind, listen ...

    int kq = kqueue();

    struct kevent ev;
    EV_SET(&ev, server_fd, EVFILT_READ, EV_ADD, 0, 0, NULL);
    kevent(kq, &ev, 1, NULL, 0, NULL);

    struct kevent events[MAX_EVENTS];

    while (1) {
        int nev = kevent(kq, NULL, 0, events, MAX_EVENTS, NULL);

        for (int i = 0; i < nev; i++) {
            int fd = events[i].ident;

            if (fd == server_fd) {
                int client_fd = accept(server_fd, NULL, NULL);

                EV_SET(&ev, client_fd, EVFILT_READ, EV_ADD, 0, 0, NULL);
                kevent(kq, &ev, 1, NULL, 0, NULL);
            }
            else {
                char buffer[1024];
                ssize_t bytes = recv(fd, buffer, sizeof(buffer), 0);

                if (bytes <= 0) {
                    EV_SET(&ev, fd, EVFILT_READ, EV_DELETE, 0, 0, NULL);
                    kevent(kq, &ev, 1, NULL, 0, NULL);
                    close(fd);
                }
                else {
                    send(fd, buffer, bytes, 0);
                }
            }
        }
    }

    return 0;
}
```

### I/O 멀티플렉싱 비교

| 구분 | select | poll | epoll | kqueue |
|------|--------|------|-------|--------|
| **플랫폼** | 모든 플랫폼 | POSIX | Linux | BSD/macOS |
| **fd 제한** | FD_SETSIZE (1024) | 없음 | 없음 | 없음 |
| **시간 복잡도** | O(n) | O(n) | O(1) | O(1) |
| **메모리 복사** | 매번 전체 복사 | 매번 전체 복사 | 없음 | 없음 |
| **Edge Triggered** | 불가 | 불가 | 가능 | 가능 |
| **파일 지원** | 가능 | 가능 | 제한적 | 가능 |

