### TypeScript 컴파일러의 AST

```typescript
// TypeScript AST 예시 (ts.Node)
import * as ts from "typescript";

// 소스 코드를 AST로 파싱
const sourceFile = ts.createSourceFile(
    "example.ts",
    `function greet(name: string): string {
        return "Hello, " + name;
    }`,
    ts.ScriptTarget.Latest,
    true
);

// AST 순회
function visit(node: ts.Node) {
    if (ts.isFunctionDeclaration(node)) {
        console.log("Function:", node.name?.getText());
        node.parameters.forEach(param => {
            console.log("  Param:", param.name.getText());
            if (param.type) {
                console.log("  Type:", param.type.getText());
            }
        });
    }
    ts.forEachChild(node, visit);
}

visit(sourceFile);

// AST 변환 (Transformer)
const transformer: ts.TransformerFactory<ts.SourceFile> = (context) => {
    return (sourceFile) => {
        const visitor: ts.Visitor = (node) => {
            // console.log 호출을 제거
            if (ts.isCallExpression(node) &&
                ts.isPropertyAccessExpression(node.expression) &&
                node.expression.name.getText() === "log") {
                return ts.factory.createVoidZero(); // void 0으로 대체
            }
            return ts.visitEachChild(node, visitor, context);
        };
        return ts.visitNode(sourceFile, visitor) as ts.SourceFile;
    };
};
```

### Babel의 AST (JavaScript)

```javascript
// Babel AST 사용
const parser = require("@babel/parser");
const traverse = require("@babel/traverse").default;
const generate = require("@babel/generator").default;
const t = require("@babel/types");

// 파싱
const code = `const square = (n) => n * n;`;
const ast = parser.parse(code, {
    sourceType: "module",
    plugins: ["jsx", "typescript"]
});

// 순회 및 변환
traverse(ast, {
    // 화살표 함수를 일반 함수로 변환
    ArrowFunctionExpression(path) {
        const { params, body } = path.node;

        // 표현식 바디를 블록으로 변환
        const newBody = t.isBlockStatement(body)
            ? body
            : t.blockStatement([t.returnStatement(body)]);

        // FunctionExpression으로 교체
        path.replaceWith(
            t.functionExpression(null, params, newBody)
        );
    },

    // const를 var로 변환
    VariableDeclaration(path) {
        if (path.node.kind === "const" || path.node.kind === "let") {
            path.node.kind = "var";
        }
    }
});

// 코드 생성
const output = generate(ast, {}, code);
console.log(output.code);
// var square = function (n) { return n * n; };
```

### ESLint 규칙 작성

```javascript
// ESLint 커스텀 규칙 (no-console)
module.exports = {
    meta: {
        type: "suggestion",
        docs: {
            description: "disallow console statements",
            category: "Best Practices"
        },
        fixable: "code",
        schema: []
    },

    create(context) {
        return {
            // console.* 호출 탐지
            CallExpression(node) {
                if (node.callee.type === "MemberExpression" &&
                    node.callee.object.name === "console") {

                    context.report({
                        node,
                        message: "Unexpected console statement.",
                        fix(fixer) {
                            // 자동 수정: 문장 전체 삭제
                            return fixer.remove(node.parent);
                        }
                    });
                }
            },

            // var 사용 금지
            VariableDeclaration(node) {
                if (node.kind === "var") {
                    context.report({
                        node,
                        message: "Use let or const instead of var.",
                        fix(fixer) {
                            return fixer.replaceTextRange(
                                [node.start, node.start + 3],
                                "let"
                            );
                        }
                    });
                }
            }
        };
    }
};
